quests[85472] = { id = 85472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kostenlose Reagenzien!", sourceObjective = "Sprecht mit dem Alchemisten des Dampfdruckkartells und folgt seinen Anweisungen, um einen Trank aus geplünderten Zutaten zu brauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85473] = { id = 85473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extrablatt! Extrablatt!", sourceObjective = "Verteilt Zeitungen an die uninformierten Bürger in Lorenhall.", sourceObjectiveStatus = "unverified-source-field" }
quests[85474] = { id = 85474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ross Ratatouille im Visier" }
quests[85475] = { id = 85475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse im Sand", description = "Willkommen zurück. Maru sucht wieder nach Euch. Sie sagt, nur Ihr habt das Können, um ihr zu helfen.\n\n<Das Geächze und die Beschwerden der Menge werden lauter.>\n\nOh, macht Euch um mich keine Sorgen. Ich bin hier... wie immer...", sourceObjective = "Sprecht mit Maru.", completion = "Hey! Ich hab einen Auftrag, der perfekt für Euch iszt!", sourceObjectiveStatus = "unverified-source-field" }
quests[85476] = { id = 85476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergrabener Szatzs", description = "Hallo, <Groszer/Grosze>! Ihr werdet esz kaum glauben, aber ich hab gehört, tasz irgendwo in Tanarisz ein echter Szatz verszteckt iszt!\n\nIch hab meine überragenten Szleichkünszte eingeszetszt und mir eine Kopie vom erszten Rätszel gesznappt. Und weil Ihr szo gut darin szeid, szie zu löszen, geb ich szie Euch!", sourceObjective = "Findet den vergrabenen Schatz.", completion = "Boah, wasz für ein genialer Szatsz! Den nehme ich, danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[85477] = { id = 85477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie verloren, so gefunden?", description = "Ich bin völlig erschlagen. Gerade stürmte hier eine ganze Meute von Leuten rein und alle beschwer... ich meine, reichten mit großer Leidenschaft Verlustmeldungen ein, aber alle gleichzeitig.\n\nIch hab versucht, mir alle Details zu notieren, aber vor lauter Stress sind sie durcheinander geraten.\n\nIch habe diesen Haufen an Sachen, die im Laufe des Tages gefunden wurden, und ich bin mir fast sicher, dass es die Dinge sind, von denen die Leute geredet haben. Könntet Ihr einen Blick auf meine Notizen werfen und rausfinden, welcher Gegenstand zu wem gehört?", sourceObjective = "Bringt die verlorenen Sachen zu ihren richtigen Besitzern.", completion = "Ihr seid mit den Sachen fertig? Oh, Ihr seid ein Geschenk des Himmels! Ich bin fast überrascht, dass nicht mehr Leute etwas bei den Festlichkeiten verbummelt haben. Aber ich platze fast vor Dankbarkeit, dass Ihr die Pechvögel mit ihren geliebten Schätzchen wiedervereint habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[85479] = { id = 85479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht sie alle, jagt sie hoch" }
quests[85481] = { id = 85481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rasante Gratwanderung", description = "Unser Schieferrückenalpha muss etwas Energie abbauen. Ich glaube, er ist auf ein Wettrennen aus.\n\nEr scheint Euch am meisten zu mögen. Würdet Ihr gegen ihn antreten?", sourceObjective = "Fordert den Schieferrückenalpha zu einem Wettrennen heraus.", completion = "Ah, das Alphatier wirkt erschöpft. Ihr habt meinen Dank... und ich meinen Wetteinsatz.", sourceObjectiveStatus = "unverified-source-field" }
