quests[85499] = { id = 85499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des einen Goblins Müll" }
quests[85500] = { id = 85500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährlicher Abfall" }
quests[85502] = { id = 85502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festtagsreflektionen", description = "Oh, Ihr seid zurück. Gut. Ich habe hier alle Hände voll zu tun und Detektiv Jones hat um Eure Hilfe bei einem neuen Fall gebeten.\n\nNicht, dass es etwas auszumachen scheint. Denn trotz all dem Guten, das wir für die Gäste tun, ist diese Schlange... wenn man es so noch nennen kann... nur noch länger geworden!\n\nIch sollte mich wieder an die Arbeit machen und Ihr solltet Euch mit Detektiv Jones unterhalten.", sourceObjective = "Sprecht mit Detektiv Jones.", completion = "Habt Ihr einen Moment? Wir haben eine ganz besonderen Fall vor uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[85503] = { id = 85503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine überraschende Untersuchung", description = "Na sieh mal einer an. Wer kommt denn da zurück, um mehr Fälle zu lösen?\n\nEs scheint, als hätte Chromie wieder an der Zeit rumgepfuscht, weshalb jetzt einige Hochstapler auf dem Gelände der Feierlichkeiten aufgetaucht sind.\n\nIhr müsst nur herausfinden, wer nicht hergehört, und ihn dann zu Chromie schicken. Das sollte doch ein Klacks für Euch sein.", sourceObjective = "Löst den Fall, den Detektiv Jones Euch gegeben hat.", progress = "Wie läuft es?", completion = "Was für eine Überraschung! Es ist schön, sich einen Moment entspannen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[85512] = { id = 85512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fälschungen aufspüren" }
