quests[85523] = { id = 85523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschimmelte Feierkiste", description = "<Die Kiste ist überwuchert von einem wachsenden Schimmelpilz aus dem feuchtwarmen Dschungelklima. Aber wie es scheint, habt Ihr die Kiste gefunden, bevor die Waren darin in Mitleidenschaft gezogen wurden. Alyx wäre sicher dankbar, die Vorräte zurückzubekommen.>", sourceObjective = "Bringt die verschimmelte Feierkiste zu Alyx zurück.", progress = "Oh, ich habe so viel zu tun. Doch womit kann ich Euch helfen?", completion = "Oh, Ihr habt eine fehlende Kiste gefunden! Das ist ja toll!\n\nWas ist dieses schwarze Zeug da? Setzt sie doch einfach ab und ich kümmere mich später darum.\n\nIch bin wirklich dankbar, dass Ihr sie zurückgebracht habt. Wenn Ihr noch mehr findet, bringt sie bitte auch zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[85524] = { id = 85524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Düsternisverschworenen entwaffnen" }
