quests[85527] = { id = 85527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bukanierbonzai" }
quests[85528] = { id = 85528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekruiteamung" }
quests[85529] = { id = 85529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergangener Ruhm", description = "Marrans \"Rote Dämmerung\" hat die Stadt verlassen und in Stromgarde ist wieder Frieden eingekehrt.\n\nZumindest vorerst.\n\nFaerin ist aufgebrochen. Sie sagte, sie wolle nach Neuhof und zur Zuflucht, aber ich denke, sie wollte einfach weg aus Stromgarde.\n\nSie kam mit so viel Enthusiasmus hierher. Ich hätte diese Begeisterung nicht so hart dämpfen sollen. Es war wohl ich, der eine Lektion zu lernen hatte.\n\nLasst uns nach ihr sehen.", sourceObjective = "Sprecht mit Faerin am Hochstand.", progress = "<Faerin wirkt gedankenverloren, als sie erneut zum Thoradinswall blickt.>", completion = "Danath hat recht. Legenden sind eben nur Legenden. Wir dürfen uns nicht vom Stolz blenden lassen und versuchen, in ihnen zu leben.\n\nStattdessen sollten sie uns dazu inspirieren, die Welt so zu gestalten, wie sie sein sollte.\n\nSo das Licht will, werden wir die Vergangenheit ehren, doch für eine bessere Zukunft arbeiten. Für uns alle.", sourceObjectiveStatus = "unverified-source-field" }
quests[85531] = { id = 85531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdverkrusteter Edelstein", sourceObjective = "Das Werk der Durchtrennten Fäden geht rasch voran. Daher haben unsere Gönner beschlossen, Euren fortlaufenden Einsatz zu belohnen.\n\nNehmt das und verschwindet. Ihr zieht Argwohn auf Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[85532] = { id = 85532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Reichtum eines Königreichs", sourceObjective = "Das Werk der Durchtrennten Fäden geht rasch voran. Daher haben unsere Gönner beschlossen, Euren fortlaufenden Einsatz zu belohnen.\n\nNehmt das und verschwindet. Ihr zieht Argwohn auf Euch.", sourceObjectiveStatus = "unverified-source-field" }
