quests[85535] = { id = 85535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kej", sourceObjective = "Das Werk der Durchtrennten Fäden geht rasch voran. Daher haben unsere Gönner beschlossen, Euren fortlaufenden Einsatz zu belohnen.\n\nNehmt das und verschwindet. Ihr zieht Argwohn auf Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[85536] = { id = 85536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resonanzkristalle", sourceObjective = "Die Arathi wissen Eure Hilfe in diesen gefährlichen Landen wirklich zu schätzen. Nehmt dies bitte als Zeichen unserer Dankbarkeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[85537] = { id = 85537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristalle", sourceObjective = "Die Arathi wissen Eure Hilfe in diesen gefährlichen Landen wirklich zu schätzen. Nehmt dies bitte als Zeichen unserer Dankbarkeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[85538] = { id = 85538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leuchties", sourceObjective = "So hilfreich! Kobolde danken Euch. Irdene danken Euch. Die Versammlung dankt Euch! \n\nKerze für Euch! Keine bessere Belohnung als das!\n\nNein, diese Kerze nicht aus Ohrenschmalz gemacht. Ist aus Bienenwachs! Riecht so gut! Ihr mögt schöne Gerüche, ja? Wenn nicht, wollt Ihr vielleicht von mir weggehen, ha, ha, ha! Entschuldigung.", sourceObjectiveStatus = "unverified-source-field" }
quests[85539] = { id = 85539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nehmt Kerze!", sourceObjective = "Dankbarkeit wird ausgedrückt. Bitte nehmt dies als Belohnung für all Eure harte Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
