quests[85544] = { id = 85544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viel kleines Glitzerzeug!", sourceObjective = "Dankbarkeit wird ausgedrückt. Bitte nehmt dies als Belohnung für all Eure harte Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[85545] = { id = 85545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resonanzkristalle", sourceObjective = "Aufgabe abgeschlossen. Der Rat belohnt Euch für Eure Hilfe bei der Wiedervereinigung der Irdenen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85546] = { id = 85546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resonanzkristalle", sourceObjective = "Ihr seid eine geschätzte Bereicherung für den Rat, {name}. Bitte nehmt dieses Zeichen unserer Dankbarkeit an, auf dass Ihr jetzt und immerdar als Ehrenratsmitglied bekannt sein möget.", sourceObjectiveStatus = "unverified-source-field" }
quests[85553] = { id = 85553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebenjob: Auf Krabbenfühlung", description = "Nahrung ist eine entscheidende Ressource für jede Mannschaft, die es wagt, zur See zu fahren. Schießpulver ebenso.\n\nLasst uns zwei Fliegen mit einer Klappe schlagen und uns einige dieser Bomben an der Kaja'Küste besorgen.\n\nAber lasst Euch dabei nicht in die Luft jagen, ja?", sourceObjective = "Sammelt 15 Krabbenfleischpulver von Bombenhülsenkrabben an der Kaja'Küste.", progress = "Wir brauchen Zeit, das Pulver von den Krabben zu trennen, bringt sie also schnell her!", completion = "Sieh sich einer das an! Genug Fleisch, um eine ganze Crew und noch mehr zu ernähren.\n\nWir müssen bloß vorsichtig sein, wenn wir das ganze Schießpulver entfernen. Wär doch schade, wenn jemand eine Hand bei der Zubereitung verliert.", sourceObjectiveStatus = "unverified-source-field" }
quests[85554] = { id = 85554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebenjob: Wir brauchen Eier!", description = "Pterrordaxeier sind in Lorenhall der letzte Schrei. Und es würde der Schwarzmeer AG nicht gut zu Gesicht stehen, wenn wir keine begehrten Luxusgüter importieren könnten.\n\nWenn Ihr Euch ein bisschen Gold verdienen wollt, geht zur Kaja'Küste und sammelt welche für uns.\n\nOh, aber nehmt nicht zu viele. Die Kunden heutzutage lieben es, wenn wir unsere Produkte als \"nachhaltig\" auszeichnen.", sourceObjective = "Sammelt 8 Pterrordaxeier an der Kaja'Küste.", completion = "Die werden in den noblen Frühstückscafés ein Vermögen einbringen, darauf könnt Ihr wetten.", sourceObjectiveStatus = "unverified-source-field" }
quests[85560] = { id = 85560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TEST" }
quests[85562] = { id = 85562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zäher als gedacht", description = "Hah! Ich hab mich nie besser gefühlt! Jetzt erobern wir zurück, was Schwarzmeer rechtmäßig zusteht, {name}.\n\nSie haben unser geliebtes Hauptquartier in eine Schmugglerhöhle für diesen fauligen Schlick verwandelt. So viele Schwarzblutkisten können wir jetzt nicht direkt beseitigen, aber sie können ihre Fracht ohne Nachschub an Leuten nicht transportieren. Dezimieren wir sie.", sourceObjective = "Erobert die Hafenbehörde von den Truppen der Düsternisverschmolzenen zurück.", progress = "Es gibt Blut zu vergießen!", completion = "Gallywix sollte es nach dieser Sache besser wissen, als noch mal mit Schwarzmeer die Säbel zu kreuzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85570] = { id = 85570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das zerlumpte Tagebuch", description = "<Das Tagebuch zerfällt fast in Euren Händen, als Ihr es durchblättert.\n\nDie wenigen Seiten, die noch übrig sind, sind mit einer krakeligen Schrift gefüllt.\n\nVielleicht wäre Stellin Verasa im Lager an diesem Tagebuch interessiert.>", sourceObjective = "Bringt das Tagebuch zu Stellin Verasa im Lager auf der Sireneninsel.\n\nBereitgestellter Gegenstand:", completion = "Oh, hallo, {name}! Was habt Ihr da?", sourceObjectiveStatus = "unverified-source-field" }
quests[85571] = { id = 85571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In alle Winde verstreut", description = "Du meine Güte! In diesem Tagebuch fehlen viele Seiten!\n\n<Stellin blättert durch das Tagebuch und achtet darauf, dass keine losen Seiten herausfallen.>\n\nDieses Tagebuch sieht nicht sehr alt aus... und es scheint von Menschen gemacht zu sein. Erklärt das, was mit den Menschen passiert ist, die hierherkamen? Was für ein Rätsel!\n\nAber es wäre weniger rätselhaft, wenn wir die fehlenden Seiten finden könnten... Würdet Ihr nach ihnen Ausschau halten, wenn Ihr da draußen unterwegs seid?", sourceObjective = "Sammelt 5 Tagebuchseiten auf der Insel.", progress = "Habt Ihr noch mehr Seiten aus dem Tagebuch gefunden?", completion = "Schaut Euch diese ganzen Seiten an!\n\nAusgezeichnete Arbeit, {name}! Doch nun kommt der schwierigste Teil...", sourceObjectiveStatus = "unverified-source-field" }
quests[85572] = { id = 85572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gemeinsame Anstrengung", description = "Das ist ja ein schönes Durcheinander, das Ihr mir da beschert habt. All diese Seiten... aber in welcher Reihenfolge?\n\nAha!\n\nDieses Tagebuch scheint einem Kul Tiraner gehört zu haben, der hergezogen ist...\n\n<Stellin schaut Euch mit vor Aufregung leuchtenden Augen an.>\n\n... und es könnte der Schlüssel sein, um etwas über ihre Zeit auf der Insel zu erfahren.\n\nAber die Seiten sind kaum zu entziffern... Vielleicht sollten wir herumfragen, ob jemand sie lesen kann.\n\nHier, nehmt Euch ein paar Seiten und hört Euch im Lager um. Ich werde weiter versuchen, diese Schriften zu entschlüsseln.", sourceObjective = "Fragt Alta, Krabbler und Ricket, ob sie das Tagebuch lesen können.", progress = "<Stellin rückt ihre Brille zurecht und verzieht das Gesicht.>\n\nDas... scheint die Unterschrift des Autors zu sein. Had... ist das ein \"D\" oder ein \"l\"\n\nHad... do... k... Oh! Haddock? Oder vielleicht ist das ein \"E\".", completion = "Oh! Bin ich froh, dass Ihr hier seid, {name}. Bei dem Tagebuch ist mir ein Durchbruch gelungen, doch zuerst will ich wissen, was Ihr gefunden habt.\n\nHabt Ihr etwas Interessantes in Erfahrung gebracht? Konnte irgendwer die Handschrift entschlüsseln?", sourceObjectiveStatus = "unverified-source-field" }
quests[85573] = { id = 85573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich zur Ruhe gebettet", description = "<Stellin hört zu, als Ihr erklärt, was Ihr erfahren habt, und nickt ernst.>\n\nDieser arme Kerl gehörte zu einer Mannschaft, die auf einem Schiff, der Säuselnden Magd, hersegelte. Sie wurden von einem Sturm fast ausgelöscht, aber dann verschwanden auch die Überlebenden!\n\nEr war der letzte, und am Ende hat auch er es nicht geschafft. Vielleicht könnten wir seine Erinnerung zur Ruhe legen.\n\nIch habe hinter dem Stützpunkt der Kul Tiraner einen Friedhof entdeckt. Vielleicht bringt es seiner Erinnerung etwas Frieden, wenn wir das Tagebuch dort zwischen die Gräber seiner Mannschaft legen.", sourceObjective = "Bringt das zerlumpte Tagebuch aus Kul Tiras auf den Friedhof, der sich hinter der Kul Tiraner Basis in den Verlassenen Minen befindet.", progress = "{name}, habt Ihr den Friedhof gefunden?", completion = "Gut. Ich bin froh, dass das erledigt ist. Ich hoffe, dass er nun mit seinen Kameraden und seiner Mannschaft Ruhe findet.\n\nIch konnte eine Kopie des Tagebuchs anfertigen, falls Ihr es lesen wollt. Ich dachte, es könnte nützlich sein.\n\n<Stellin verstummt und versinkt in Gedanken.>\n\nIch frage mich allerdings... was ist mit der Mannschaft passiert? Warum war der Autor am Ende allein?\n\nAuf dieser Insel gibt es so viele Rätsel zu lösen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85574] = { id = 85574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebelhafte Feierkiste", description = "<Diese Kiste springt vor dunkler, nekromantischer Energie immer wieder aus dieser Existenzebene heraus und wieder hinein. So oder so, Alyx würde es vermutlich begrüßen, wenn diese Vorräte wieder zurückgebracht werden.>", sourceObjective = "Bringt die nebelhafte Feierkiste zu Alyx zurück.", progress = "Ja?", completion = "Oh, Ihr habt eine fehlende Kiste gefunden! Wunderbar!\n\nIch bin wirklich dankbar, dass Ihr sie zurückgebracht habt. Wenn Ihr noch mehr findet, bringt sie bitte auch zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[85589] = { id = 85589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerknitterte Seiten", description = "Viele der Wyvern auf dieser Insel bauen ihre Nester aus Papieren, Schriftrollen und Dokumenten, die sie aus den Ruinen der Insel geplündert haben.\n\nDaher könnten ihre Nester die Hinweise enthalten, die wir brauchen, um die ganze Geschichte dieses Ortes zu verstehen.\n\nUnsere Späher haben Haltegriffe installiert, mit denen Ihr zu ihren Nestern klettern könnt, aber Ihr könnt jedes Mittel nutzen, um die Papiere zu bergen, die die Wyvern als Nistmaterial verwendet haben. Unser Wissen über die Geschichte der Insel hängt davon ab!", sourceObjective = "Sammelt 15 Nistpapiere aus den Nestern der Wyvern auf der Insel.", progress = "Ich möchte unbedingt die Dokumente sehen, die die Wyvern mitgenommen haben!", completion = "Sie sind ein wenig angeknabbert und zerkaut, aber ich kann die Schrift auf diesen Seiten noch erkennen. Gute Arbeit, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[85648] = { id = 85648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Tiefenforschers: Erdwühlerminen", description = "UNTERSTÜTZUNG GESUCHT\n\nDie Probleme in den Erdwühlerminen gehen weiter. Wer damit umgehen kann, wird ordentlich entlohnt.", sourceObjective = "Schließt die Erdwühlerminen auf beliebigem Schwierigkeitsgrad ab.", progress = "Habt Ihr Euch die Aufgabe für Erdwühlerminen geschnappt?", completion = "Das ist ein Problem weniger.", sourceObjectiveStatus = "unverified-source-field" }
quests[85649] = { id = 85649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Tiefenforschers: Die Wasserwerke", description = "ACHTUNG\n\nDie Wasserwerke sind instabil geworden. Hilfe bei der Behebung der Probleme ist erforderlich.", sourceObjective = "Schließt die Tiefe der Wasserwerke auf beliebigem Schwierigkeitsgrad ab.", completion = "Lobenswerte Arbeit in den Wasserwerken.", sourceObjectiveStatus = "unverified-source-field" }
quests[85653] = { id = 85653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Zeh ins Wasser halten", description = "Euer Ring hat ziemliches Aufsehen erregt, was? Und die Geschichte dahinter... Vrykul? Jemand namens Cyrce?\n\nIch weiß, dass Ihr mit Bargus die Insel erkundet habt, um mehr über den Ring herauszufinden, aber... vielleicht solltet Ihr Eure Aufmerksamkeit dem Meer zuwenden.\n\nNehmt Euren Ring mit ins Wasser und schaut, was passiert. Bringt mir alles, was Ihr findet. Ich bin zwar noch etwas unerfahren, aber vielleicht kann ich das, was Ihr findet, wieder zusammensetzen.", sourceObjective = "Sucht in den Gewässern um die Sireneninsel nach weiteren Citrinen.", progress = "Kobyss würde bei jedem Thalassophobie auslösen. Ihr seid eine mutige Seele, wenn Ihr in diesem Wasser nach Edelsteinen sucht.", completion = "<Lehrling Tanmar nimmt die drei singenden Bruchstücke und schaut sie skeptisch an.>\n\nMan merkt, dass hier Macht drinsteckt. Ich... hoffe, ich kann sie sicher verschmelzen. Wird schon schiefgehen. Oder auch nicht. Ha.\n\n<Lehrling Tanmar nimmt ein Fläschchen mit einer zähen, goldenen Flüssigkeit heraus und beginnt, sie zusammenzufügen. Die Flüssigkeit leuchtet auf und der Citrin ist wieder ganz. Er reicht Euch den reparierten Citrin.>\n\nBeeindruckt? Müsst Ihr nicht sein. Um ehrlich zu sein, war das nur ein besserer Kleber. Aber hoffentlich wird dieser Ring unser Wissen über die Insel erweitern!", sourceObjectiveStatus = "unverified-source-field" }
quests[85654] = { id = 85654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufladen und losstürmen", description = "Na, sieh mal an. Wenn das mal nicht {name} ist. Ihr seid im Lager in aller Munde.\n\n<Didi nimmt Eure Hand und schaut sich Euren Ring genau an.>\n\nDer Ring an Eurem Finger ist wirklich seltsam. Wollt Ihr wirklich keinen anderen haben?\n\n<Didi schaut zu Euch auf und zwinkert.> Ich nehme Euch nur auf den Arm. Mal sehen, was wir damit machen können!\n\nBesorgt mir genug von dem magischen Metallzeug, das wir gefunden haben, und ich kümmere mich darum, dass Ihr in den Verprügler da drüben reinkommt.\n\nEuer Ring sollte ihm den nötigen Saft geben, um richtig viel Schaden anzurichten!", sourceObjective = "Beschafft Euch genug flammengesegnetes Eisen, um den N.U.K.L.A.R.-Zielmarkierer und den TR-06 Verprügler zu testen.", progress = "Habt Ihr es geschafft, etwas Eisen zu finden und ein bisschen Chaos anzurichten?", completion = "Schön, dass es noch Leute gibt, die das Chaos genauso lieben wie ich. <Didi wischt sich eine Träne aus dem Auge.>", sourceObjectiveStatus = "unverified-source-field" }
quests[85655] = { id = 85655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entfesselung ihrer Macht", description = "Der Ring, den Ihr und Bargus gefunden habt, hat Euch über die ganze Insel geführt, damit Ihr ihre Geschichte kennenlernt und ihre Schätze findet.\n\nUnd er hat Euch bei Euren Erkundungen genau so geholfen wie im Kampf. Aber wir haben den Ring noch nie wirklich bis an seine Grenzen getestet.\n\nVielleicht sind einige ernsthafte Tests angesagt. Vielleicht können wir mehr von seinem Potenzial enthüllen, wenn wir ein wenig Gefahr ins Spiel bringen.\n\nTestet den Ring gegen jeden würdigen Gegner, den Ihr findet. Berichtet mir dann von Euren Beobachtungen.", sourceObjective = "Legt Cyrces Reif an und kämpft gegen Kreaturen auf der Sireneninsel, um seine verborgene Fähigkeit im Kampf auszulösen.", progress = "Habt Ihr mit dem Ring Kampftests durchgeführt? Was habt Ihr herausgefunden?", completion = "Was für faszinierende Ergebnisse. Trotzdem habe ich das Gefühl, dass es noch viel mehr zu lernen und zu verarbeiten gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[85656] = { id = 85656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der singende Banditenfänger", description = "Anscheinend habt Ihr das mit dem Ring langsam drauf, was? Vielleicht könnt Ihr ihn für mich einsetzen.\n\nUnsere Vorräte hier, vor allem unser Gold und das flammengesegnete Eisen, sind verschwunden!\n\n<Tanmar beugt sich vor, um zu flüstern.>\n\nNormalerweise würde ich das nicht vorschlagen, denn die Arathi sind ein vertrauenswürdiges Völkchen. Aber die Zahl der Vorfälle nimmt zu und ich frage mich, ob es einen Dieb in unserer Mitte gibt.\n\nVersucht, ihn zu finden. Er ist ziemlich dreist. Ich bin sicher, Ihr könnt ihn irgendwo auf frischer Tat ertappen!", sourceObjective = "Fangt drei Diebe.", progress = "Behaltet Eure Taschen im Auge. Allem Anschein nach wimmelt es hier vor Dieben.", completion = "Das ist ja eine ganz schöne Geschichte. Bei all den Merkwürdigkeiten, die von dieser Insel kommen, überrascht mich das aber nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[85657] = { id = 85657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cyrce wäre stolz", description = "Es ist kein Geheimnis, dass die Winde hier schrecklich sind.\n\nAber ich glaube nicht, dass wir diesem Ring eine faire Chance gegeben haben, sie zu bekämpfen. Ich meine, mit dem Ding kann man wie ein Fisch schwimmen, Tornados aus dem Nichts erzeugen und sogar magische Kisten sichtbar machen! Da kommt es doch wohl auch mit 'nem bisschen schlechtem Wetter klar, oder?\n\nSteigt mit Eurem Ballon auf und versucht, ihn mit Eurem Ring stabil zu halten. Vielleicht finden wir heraus, wie wir in der Luft bleiben können!", sourceObjective = "Fliegt mit dem Himmelsdorn, um zu sehen, ob Cyrces Reif Euch vor den starken Winden schützen kann.", progress = "Wenn der Ring uns vor Stürmen schützen könnte, wäre das fantastisch!", completion = "Der Ring scheint auch bei starkem Wind und Sturm zu funktionieren!\n\nIhr würdet mir den Ring nicht mal ausleihen, oder? Damit könnte ich bestimmt ein paar Rennen gewinnen. Wir könnten Partner sein! Wir könnten unsere Gewinne 30/70 teilen. Wie wär's mit 40/60? Hach, Ihr macht mich fertig. Gut, 50/50?\n\nImmer noch nicht? Na gut, vergesst es. Man wird ja wohl noch träumen dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85664] = { id = 85664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Tiefenforschers: Nachtsturzsanktum", description = "HILFERUF!\n\nDer Orden der Nacht hat an einem Ort namens Nachtsturzsanktum möglicherweise eine Basis errichtet.\n\nEs ist von äußerster Wichtigkeit, dass wir ihrem Vorhaben so bald wie möglich ein Ende setzen.", sourceObjective = "Schließt die Tiefe des Nachtsturzsanktums auf beliebigem Schwierigkeitsgrad ab.", completion = "Mir ist zu Ohren gekommen, dass jemand den Machenschaften des Ordens der Nacht ein Ende gesetzt hat. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[85666] = { id = 85666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Tiefenforschers: Spiralgewebe", description = "HILFE GESUCHT\n\nEs heißt, dass die Neruber im Spiralgewebe einen großen Militärapparat haben.\n\nHelft den Überlebenden des Dalaranvorfalls, indem ihr dem ein Ende setzt!", sourceObjective = "Schließt die Tiefe des Spiralgewebes auf beliebigem Schwierigkeitsgrad ab.", completion = "Ihr habt es geschafft! Das sollte unseren Truppen an der Oberfläche eine kleine Verschnaufpause verschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85667] = { id = 85667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Tiefenforschers: Tiefenfestung", description = "ANWEISUNGEN DER WEBERIN\n\nAn einem Ort namens Tiefenfestung tragen sich dunkle Machenschaften zu.\n\nSetzt dem ein Ende.", sourceObjective = "Schließt die Tiefe der Tiefenfestung auf beliebigem Schwierigkeitsgrad ab.", completion = "Exzellente Arbeit für jemanden wie Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[85678] = { id = 85678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So gut wie neu", description = "Eure Ausrüstung scheint nach Eurer letzten Reise ziemlich mitgenommen zu sein.\n\nSprecht mit Rüstmeisterin Richter, um sie reparieren zu lassen.", sourceObjective = "Sprecht mit Rüstmeisterin Richter und wählt dann \"Alle Gegenstände reparieren\", um Eure beschädigte Ausrüstung zu reparieren.", completion = "Eure Ausrüstung sieht schon besser aus!\n\nIhr solltet sie immer reparieren lassen, damit ihr keine bösen Überraschungen erlebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[85679] = { id = 85679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So gut wie neu", description = "Eure Ausrüstung ist nach Eurem letzten Kampf fast zerstört!\n\nSprecht mit Versorger Jin'hake, um sie sofort reparieren zu lassen.", sourceObjective = "Sprecht mit Versorger Jin'hake und wählt dann \"Alle Gegenstände reparieren\", um Eure beschädigte Ausrüstung zu reparieren.", completion = "Ihr solltet Eure Ausrüstung immer reparieren lassen, wenn Ihr es in der Horde zu Ruhm und Ehre bringen wollt!", sourceObjectiveStatus = "unverified-source-field" }
quests[85710] = { id = 85710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt sie auf Größe", description = "Wir haben versucht, medizinische Untersuchungen an den Schieferrücken vorzunehmen, doch sie bringen ihren Unmut recht aggressiv zum Ausdruck.\n\nVe'nari hat uns zur Unterstützung diesen Schrumpfapparat zur Verfügung gestellt. Bitte sammelt für mich einige von ihnen ein.", sourceObjective = "Schrumpft und sammelt 10 Schieferrückenstreuner.", progress = "<Om'talad ist damit beschäftigt, zu reparieren, was wie Bissspuren an seinen Beinen aussieht.>", completion = "Ah, das ist eine deutlich besser zu bewältigende Größe. Ach, die sehen fast schon süß aus. \n\nVielen Dank. Ich führe die Untersuchungen durch und lasse sie anschließend wieder frei.", sourceObjectiveStatus = "unverified-source-field" }
quests[85711] = { id = 85711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unerbetene Rückmeldungen", description = "Alice ist zurück und sie ist eine viel bessere Köchin, als sie es je war, bevor sie eine <flüstert> Ratte wurde.\n\nAber verlasst Euch nicht nur auf mein Wort. Hier, verteilt das Essen und lasst es Euch direkt von den Gästen bestätigen!", sourceObjective = "Serviert den hungrigen Gästen Essen.", progress = "Habt Ihr das Essen schon verteilt? Wie fanden sie es?", completion = "Erstaunlich, nicht wahr?\n\nIch glaube nicht, dass sie sich schon zurückverwandeln will, zumindest nicht, bis sie ihre Fähigkeiten weiter verfeinert hat. Aber wir haben das Gegenmittel aus der Rotbeere, wenn sie so weit ist. Nochmals vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[85715] = { id = 85715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muse gesucht" }
quests[85716] = { id = 85716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runenversengter Speer", description = "<Ein mit aufwendigen Runen überzogener Speer. Angorla würde diese Waffe vielleicht studieren wollen.>", sourceObjective = "Bringt den runenversengten Speer zu Angorla auf der Treibgutbank.\n\nBereitgestellter Gegenstand:", completion = "Fantastisch! Ich kann so viel aus diesen Runen lernen, wenn ich sie aus der Nähe studiere!", sourceObjectiveStatus = "unverified-source-field" }
quests[85717] = { id = 85717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heikles Haustier" }
quests[85718] = { id = 85718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein strahlender Stein", sourceObjective = "Aufgabe abgeschlossen. Der Rat belohnt Euch für Eure Hilfe bei der Wiedervereinigung der Irdenen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85721] = { id = 85721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubtierinstinkt", description = "Das Jagdtraining mit der Dornschweifmatriarchin scheint zu funktionieren und wir möchten weiter am Ball bleiben.\n\nKönnt Ihr sie noch ein paar Schoßkäfer jagen lassen?", sourceObjective = "Bringt der Dornschweifmatriarchin 10-mal bei, wie man Schoßkäferkrabbler jagt.", completion = "Der Tod ist ein natürlicher Teil des Lebens.\n\nWenn man kein Mittler ist. Oder Astraler. Oder, na ja, auf sonstige Weise unsterblich.", sourceObjectiveStatus = "unverified-source-field" }
quests[85722] = { id = 85722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Einzahlung bitte", description = "<Nachdem Ihr der Invasion der Verschlinger ein Ende gesetzt hattet, habt Ihr diesen festen Klumpen Anima aus dem Bauch ihres Anführers herausgezogen. \n\nVe'nari könnte damit vielleicht die Biokuppeln mit Energie versorgen.>", sourceObjective = "Bringt die kristallisierte Anima zu Ve'nari in der Oase.\n\nBereitgestellter Gegenstand:", completion = "Beeindruckende Beute. Ein noch beeindruckenderer Handel.\n\nIhr werdet dafür entlohnt werden. Ich will nicht in Eurer Schuld stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85724] = { id = 85724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegenwehr", description = "Ein riesiger Hüne von einem Hobgoblin, Skeez, hat die Docks übernommen, gerade als Gallywix mich einbuchten ließ. Er hat seine Düsternisverschmolzenen hergebracht und viele Schwarzmeerkameraden sind verschwunden. Der Kapitän hat das persönlich genommen, und genauso ergeht es mir. Skeez glaubt, Gallywix wird ihn beschützen.\n\nBringen wir ihn um.", sourceObjective = "Tötet Dockmeister Skeez.", progress = "Noch an einem Stück, hm?", completion = "So sorgen wir für Gerechtigkeit, ob auf See oder im Hafen: mit dem Säbel.", sourceObjectiveStatus = "unverified-source-field" }
quests[85730] = { id = 85730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet, was übrig bleibt", description = "Der Verlust einer Biokuppel ist unvorstellbar. Der Tod von Om'bera...\n\n<Die Schultern des Mittlers heben sich und fallen auf eine Art, die ein Seufzen vermuten lässt, auch wenn kein Atmen zu hören ist.>\n\nIch kann nicht gehen, ohne die Forschungskisten zu bergen! Ihre Arbeit muss weiterleben, auch wenn sie es nicht kann. Laut Om'beras Manifest gab es mindestens fünf Kisten voller Forschungsmaterial und Ressourcen.", sourceObjective = "Bringt 5 geraubte Forschungskisten zu Om'resh.", progress = "Ich verstehe die Ödnisbewohner nicht. Ich dachte, sie wären einst Orakel des ungezähmten K'areshs gewesen. Verehrer der Natur. Warum sollten sie von unseren Kuppeln stehlen und die Mission des Bundes sabotieren?", completion = "Danke, dass Ihr die Kisten zurückgebracht habt. Om'beras Forschung wird uns helfen, im Laufe der Zeit ein stabiles Biom zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[85731] = { id = 85731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsquest" }
quests[85732] = { id = 85732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnelle Schädlingsbekämpfung" }
