quests[85773] = { id = 85773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister zu vermieten" }
quests[85780] = { id = 85780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genau wo wir ihn haben wollen", description = "Gallywix ist am Boden, aber es ist noch nicht erledigt.\n\nDas Garbagio ist wie eine Festung erbaut. Wenn wir verhindern wollen, dass er Lorenhall bedroht, oder ganz Azeroth, müssen wir uns was ausdenken, um ihn rauszulocken. Kommt mit mir und den anderen Bossen am Hotel Inkontinental zusammen.", sourceObjective = "Kehrt zum Hotel Inkontinental zurück und sprecht mit Gazlowe.", completion = "Wir müssen der Bevölkerung von Lorenhall für die Gelegenheit danken, Gallywix ein für alle Mal zur Strecke zu bringen.\n\nUnd die Gelegenheit lass ich nicht verstreichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85797] = { id = 85797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Messerkampf" }
quests[85804] = { id = 85804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Mutter für alle Fallen", description = "Ich helfe gern auf jede erdenkliche Weise.\n\nUm Alleria zu finden, müsst Ihr weit nach Norden fliegen. Sie jagt einen neuen Leutnant der Schattenwache in der Hoffnung, ihm Informationen entlocken zu können.\n\nZuletzt hielt sie sich angeblich am Rand eines Ortes namens Laacunas Bruch auf.", sourceObjective = "Findet Alleria Windläufer bei Laacunas Bruch.", completion = "Die Vision meiner Schwester darf sich nicht bewahrheiten!\n\n<Alleria wirkt frustriert.>\n\nIch wünschte, ich könnte zurückkehren, aber das ist einfach nicht möglich. Hier jedoch kann ich etwas unternehmen, und Ihr beide könnt helfen, während wir die Angelegenheit besprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85805] = { id = 85805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angesehen bei den Kartellen von Lorenhall", description = "Vielen Dank für die harte Arbeit!\n\nWir haben ein paar Vorräte für Euch im Hotel vorbereitet. Kommt und holt sie Euch von Smaks Oberskimmer.", sourceObjective = "Sprecht mit Smaks Oberskimmer im Hotel Inkontinental.", completion = "Bitte sehr!", sourceObjectiveStatus = "unverified-source-field" }
quests[85806] = { id = 85806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrfürchtig beim Bilgewasserkartell", description = "Ihr habt dem Bilgewasserkartell geholfen, als es Euch brauchte. Das wird man nicht vergessen.\n\nSprecht mit Rocco Ratschbumm, er wird sich um Euch kümmern.", sourceObjective = "Sprecht mit Rocco Ratschbumm im Schrottladen.", completion = "He, das ist für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[85807] = { id = 85807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrfürchtig bei der Schwarzmeer AG", description = "In der Schwarzmeer AG läuft es gut, dank Euch.\n\nBootsmann Harti hat Euren Anteil an der Beute vorbereitet... Das heißt, eine ansehnliche Belohnung für Eure Arbeit.", sourceObjective = "Sprecht mit Bootsmann Harti bei der Hafenbehörde.", completion = "Hier ist Euer Anteil, alles in Ordnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[85808] = { id = 85808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrfürchtig bei Düsternisverschmolzene Lösungen", description = "Nur wenige helfen den Düsternisverschmolzenen, darum möchten sie sich bedanken.\n\nSie müssen es still und leise tun, deshalb findet Ihr Lage Fiesmöpp unten in der Kanalisation bei Bruchbudenhügel.", sourceObjective = "Sprecht mit Lage Fiesmöpp in der Kanalisation nahe Bruchbudenhügel.", completion = "Bitte sehr, Kumpel. Ich weiß Eure Hilfe zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85809] = { id = 85809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrfürchtig beim Dampfdruckkartell", description = "Das Dampfdruckkartell möchte sich bei Euch für all die Arbeit bedanken, die Ihr geleistet habt.\n\nBefolgt alle Sicherheitsprotokolle und sucht Laborassistentin Laszla auf, um eine Belohnung zu erhalten.", sourceObjective = "Sprecht mit Laborassistentin Laszla bei den Dampfdrucklaboren.", completion = "Wir haben etwas für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[85810] = { id = 85810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrfürchtig bei der Venture Co.", description = "Die Venture Co. möchte Euch für all die Arbeit belohnen, die Ihr für uns gemacht habt.\n\nSprecht mit Schredd dem Verschrotter, um Eure Belohnung zu erhalten.", sourceObjective = "Sprecht mit Schredd dem Verschrotter beim Venturerondell.", completion = "Das habt Ihr gut gemacht. Das gehört Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[85811] = { id = 85811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thrayir, Augen der Sirene", description = "<Die Macht des Sturms hat Thrayir, Augen der Sirene, neu gebildet. Er wartet darauf, dass Ihr ihn annehmt.>", sourceObjective = "Nehmt Thrayir, Augen der Sirene in Empfang.", completion = "<Thrayir, Augen der Sirene ist bereit für den Einsatz.>", sourceObjectiveStatus = "unverified-source-field" }
quests[85812] = { id = 85812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beraubt die Räuber" }
