quests[85861] = { id = 85861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teppichmonster!!!" }
quests[85862] = { id = 85862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pflicht eines Prinzen", description = "Heute ist ein großer Tag, Junge. Ein Truppenaufmarsch steht bevor, eine Delegation aus Eisenschmiede ist zugegen, und man munkelt, Euer Vater, ähm, König Terenas, werde selbst erscheinen, um allem beizuwohnen.\n\nIhr wurdet für Tage wie diesen geschmiedet, Arthas. Spornt Eure Männer an. Beweist Euch.\n\nBringt diese Truppen auf Vordermann. Und zweifellos juckt es Muradin auch schon wieder in den Fäusten...", sourceObjective = "Kämpft mit den Truppen in der Garnison von Lordaeron.", progress = "Du bist das Beste, was unser Königreich hervorgebracht hat, mein Sohn. Lasse uns gut dastehen vor unseren Gästen!", completion = "Gut gemacht, mein Sohn! Ich habe die Soldaten von hier aus gehört. Es klingt, als hättest du ihnen eine Lektion in Sachen Demut erteilt. Und wie du mit Muradin umgegangen bist! Aber natürlich...\n\nDafür wurdest du geboren.", sourceObjectiveStatus = "unverified-source-field" }
quests[85863] = { id = 85863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phasentauchen: Seltsame Stürme" }
quests[85864] = { id = 85864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phasentauchen: Gebrochenes Laakunit" }
quests[85869] = { id = 85869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viele Aufträge, kümmert Euch drum!", description = "Versand & Logistik testet ein neues Anreizprogramm für Fahrer.\n\nErledigt ein paar Aufträge und haltet uns auf dem Laufenden, ja?", sourceObjective = "Schließt 10 Aufträge für Versand & Logistik ab.", progress = "Zurück an die Arbeit. Zack, zack!", completion = "Tolle Arbeit da draußen. Hier, das kleine Extra, das Euch versprochen wurde. Und ein schönes Trinkgeld von der Chefin.", sourceObjectiveStatus = "unverified-source-field" }
quests[85871] = { id = 85871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrensuche: Die Streitkräfte der Klinge", description = "Xal'atath führt ein Heer aus Schatten und Trug heran.\n\nDoch sie sind nichts gegen unsere vollendeten Formen!\n\nIhr seid auserwählt und gesegnet mit der Macht N'Zoths, auf dass Ihr als sein Champion dient.\n\nZieht nun aus und vernichtet sie!", sourceObjective = "Besiegt Xal'ataths Streitkräfte", completion = "Ihr seid mit dem Staub der Schatten bedeckt wie das Blut Eurer Feinde. Gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[85873] = { id = 85873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine weitere schattenhafte Einladung", sourceObjective = "Trefft den Raumgänger in der Gründungshalle in Dornogal.", sourceObjectiveStatus = "unverified-source-field" }
quests[85874] = { id = 85874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldfischrettung" }
quests[85875] = { id = 85875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg des Lichkönigs", description = "<Eiskrone liegt vor Euch. Wartend. \n\nFrostgram fordert Euch auf...\n\n... aufzusteigen.>", sourceObjective = "Verbannt Eure Erinnerungen.", completion = "Arthas... mein Sohn.\n\n<Die Krone lastet schwer auf deinem Haupt.>\n\nDu wirst mit der Zeit lernen...\n\n<Der Wind heult in Euren Ohren.>\n\n... dass kein König ewig herrscht.", sourceObjectiveStatus = "unverified-source-field" }
quests[85876] = { id = 85876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Runen lesen", description = "Meine Neugierde ist noch immer nicht gestillt, {name}. Ich würde gerne mehr über diese Vrykul erfahren und warum sie in dieses Land gekommen sind.\n\n<Bargus' drahtige Augenbrauen ziehen sich zusammen und sein Schnurrbart kräuselt sich, während er nachdenkt.>\n\nDie Tafeln, die Ihr gefunden habt, waren bei Weitem die beste Quelle für Informationen über die Vrykul, wer auch immer \"Cyrce\" ist.\n\nVielleicht haben wir noch mehr Tafeln übersehen.\n\nIch habe hier meine Pflichten, aber bitte untersucht sie und erstattet mir Bericht.", sourceObjective = "Untersucht verschiedene runengemeißelte Tafeln in der Vergessenen Gruft.", completion = "Faszinierend. Dieser \"Galeorn\", von dem Ihr gesprochen habt und der als Thrayir bekannt ist, könnte eine weitere Untersuchung wert sein.\n\nVielleicht können wir mit den Runenschlüsseln auch mehr über seine Bedeutung herausfinden.\n\nMeine Neugierde wird wohl so schnell nicht verschwinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[85878] = { id = 85878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "O' Thanagor", description = "Ihr seid der Lichkönig.\n\nGanz Azeroth hat sich gegen Euch verschworen.\n\nZeigt ihnen, was es heißt, König zu sein.", sourceObjective = "Besiegt die Thronräuber auf der Eiskronenzitadelle.", completion = "Seine Herrschaft war kurz, aber schrecklich.", sourceObjectiveStatus = "unverified-source-field" }
quests[85879] = { id = 85879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus alt mach Profit", description = "Die Leute bei S.C.H.R.O.T.T. könnten diese Woche Verstärkung brauchen.\n\nWenn Ihr ein Stück vom Kuchen abhaben wollt, sucht einen ihrer Vertreter namens Carlo auf und fragt ihn, ob er Arbeit für Euch hat.\n\nAber wenn Ihr ein Stück Kuchen in einem der Müllhaufen findet... esst es nicht. Ich hoffe, das versteht sich von selbst.", sourceObjective = "Schließt 3 S.C.H.R.O.T.T.-Aufträge in Lorenhall ab.", progress = "Was braucht Ihr, eine Anleitung?\n\nGroße Müllhaufen. Schaufel. Legt los.", completion = "Ja, Carlo hat Euren Namen in einigen der Berichte erwähnt. Ihr seid effizient, das muss man Euch lassen.\n\nHier ist Euer Anteil an den Wiederverkäufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85884] = { id = 85884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrensuche: Der Prinz, der König werden würde", description = "Bevor ich Euch die Geschichte des Lichkönigs erzählen kann, müssen wir erfahren, wer er war, bevor er seine Krone aufsetzte.\n\nBevor er dieses verfluchte Schwert aus den Tiefen der Frostgramhöhlen zog.\n\nWir müssen über den Prinzen sprechen, dem die Welt versprochen wurde, und über die Menschen, die sich für seine Sache einsetzten.\n\nWir müssen vor vielen Jahren in Lordaeron beginnen, an einem Tag voller Pomp und Prunk.", sourceObjective = "Dies ist die Geschichte von Prinz Arthas Menethil.", completion = "<Cho ist verstummt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[85885] = { id = 85885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrensuche: Kein König herrscht ewig", description = "Was macht einen König aus? Ist es seine Krone? Ist es die Schärfe seines Schwertes? Die Kälte seines Herzens?\n\nVielleicht die unsterbliche Ergebenheit seines Volkes?\n\nGenauso wie man nur schwer sagen kann, wann ein Bäumchen ein Baum ist oder ein Berg ein Hügel, kann man auch nur schwer bestimmen, wann genau Arthas Menethil in die Erinnerung überging und der Lichkönig geboren wurde.\n\nWo zieht man die Grenze zwischen Mensch und Monster?", sourceObjective = "Hört Euch die Geschichte des Lichkönigs an.", completion = "Es ist eine düstere Geschichte, voller schrecklicher Taten und tragischer Schicksale.\n\nAber es ist eine Geschichte, die erzählt werden muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[85888] = { id = 85888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Künstlerlizenz" }
