quests[85907] = { id = 85907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grundgekrabbel - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[85913] = { id = 85913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebenjob: Aufräumarbeiten", description = "Wir brauchen jemandem mit einem starken Arm und einem noch stärkeren Magen, der uns mit all den Blutmonstern helfen kann, die in den Schallenden Tiefen aufgetaucht sind. Die Räumtrupps werden immer wieder gefressen und wir haben einen mörderischen Arbeitsplan. \n\nSeid Ihr dabei?", sourceObjective = "Tötet Blutmonstrositäten in den Zuckenden Feldern.", completion = "He, nicht schlecht. Versucht nur, keine Flecken zu hinterlassen, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[85914] = { id = 85914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebenjob: Kühle Angelegenheiten", description = "Klingt, als würden die alten Schwarzblutrohre in den Schallenden Tiefen auftauen. Aber wir haben noch keine Lösung für den ganzen Glibber gefunden, mit dem sie verstopft sind. Nach ein paar weiteren Finanzierungsmeetings sollten wir aber so weit sein.\n\nBis dahin haben wir eine kleine Belohnung für Aushilfen ausgehandelt. Damit meine ich Euch.\n\nSchafft Euch da raus und friert die Rohre wieder ein.", sourceObjective = "Steigt in den Zuckenden Feldern auf Pamsys Raketenbrett und friert die Rohre wieder ein.", completion = "Eiskalt.", sourceObjectiveStatus = "unverified-source-field" }
quests[85925] = { id = 85925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halsbrecherrennen - Halsbrecherblitz" }
quests[85926] = { id = 85926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halsbrecherrennen - Schrottplatzspurt" }
