quests[85928] = { id = 85928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halsbrecherrennen - Grundgekrabbel" }
quests[85929] = { id = 85929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archivar Rumpelschimmer", sourceObjective = "Die Freyschwörer haben seit jeher die Mondzyklen und die Himmelskörper am Firmament beobachtet. Vielleicht können wir ihre Glaubenssätze mit der Zeit übernehmen und diesen Feiertag in den kommenden Zyklen begehen.\n\nWie es unsere Sitten verlangen, sage ich Euch Lebewohl, {name}, und möchte Euch dies als Zeichen des Danks anbieten...", sourceObjectiveStatus = "unverified-source-field" }
quests[85930] = { id = 85930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archivar Kupfermoos", sourceObjective = "Wenn Ihr mir die Ehre erweist, gedenkt all der großen Taten, die ich für die Irdenen vollbrachte.\n\nIch, Togdhar der Mutige, nehme Eure Ehrenbezeugung an und biete Euch im Gegenzug ein Zeichen der Anerkennung.\n\nWie war das? Habt Ihr geglaubt, dass ich Togdhar bin?", sourceObjectiveStatus = "unverified-source-field" }
quests[85931] = { id = 85931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archivarin Farolt", sourceObjective = "Es ist ein faszinierender Gedanke, dass andere Irdene ihre Finger bei den Ereignissen im Spiel hatten, aus denen schließlich dieses \"Mondfest\" hervorging. Ich wüsste zu gern mehr darüber.\n\nWie es Sitte ist, verabschiede ich mich und biete Euch dies als Zeichen meiner Dankbarkeit an...", sourceObjectiveStatus = "unverified-source-field" }
quests[85932] = { id = 85932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archivarin Silsigra", sourceObjective = "Nachdem ich den Kobolden lauschte, die Geschichten aus der Vergangenheit an ihren Nachwuchs erzählten... sehe ich ein, dass sich hinter diesem Feiertag doch eine gewisse Weisheit verbirgt.\n\nGehabt Euch wohl, Fremdling, und lasst mich Euch dies zum Dank überreichen...", sourceObjectiveStatus = "unverified-source-field" }
quests[85933] = { id = 85933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Knythall", sourceObjective = "Das erinnert mich an einen alten Feiertag, den wir im Reich begingen. Ich kann mich kaum daran erinnern, aber ich weiß noch, wie meine Eltern diese Zeit des Jahres liebten. In solchen Momenten denke ich an meine Kinder...\n\nIch frage mich, ob auch ihre Erinnerung an mich verblasst ist. Ich jedenfalls habe sie nie vergessen.\n\nIch akzeptiere Euren Tribut und überreiche Euch im Gegenzug dies als Zeichen meines Danks... Möge die Flamme Euch beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85934] = { id = 85934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahnin Schwureid", sourceObjective = "Dieser Festtag erinnert mich vage an einen aus meiner Heimat. Wenn ich ein bisschen nachgrübeln würde, käme ich sicher darauf. Wie groß ist die Wahrscheinlichkeit, dass sie zusammenhängen? Hm, da gibt es viel zu bedenken.\n\nMöge die Flamme Euch leiten. Ich wünsche Euch alles Gute, {name}, und schenke Euch dies, wie es der Brauch will.", sourceObjectiveStatus = "unverified-source-field" }
quests[85935] = { id = 85935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahnin Ikk'zivan", sourceObjective = "Ich halte die Fäden der Geschichte in der Hand, Überkrabbler. Es ist eine schwere Last, aber eine ehrenvolle. Ihr ehrt die Menschen aus Eurer Vergangenheit, indem Ihr sie besucht. Wir ehren die Menschen aus unserer Vergangenheit, indem wir dafür sorgen, dass sie nie vergessen werden.\n\nHier, nehmt dieses Zeichen zur Erinnerung an die Lektion, die Ihr heute gelernt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[85936] = { id = 85936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahnin Ikk'xataz", sourceObjective = "Unsere Fäden mögen für andere wie eine Last wirken. Jeder trägt das Gewicht tausender Lebenszeiten an Geschichte. Dabei reichen manche Stränge bis an den Anfang unserer Zeit hier zurück.\n\nDoch ich fühle mich geehrt, diese Last zu tragen. Durch mich können andere Leben fortbestehen.\n\nHier, nehmt dieses Zeichen. Es soll Euch an die Lektion erinnern, die Ihr heute gelernt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[85941] = { id = 85941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsmoral aufwerten", description = "Gewalt liegt eigentlich nicht in meiner Natur, aber da draußen treiben sich eine Menge Düsternisverschmolzene rum. Sie belästigen die Bevölkerung sowieso schon, und wenn Ihr anfangt, Fragen zu stellen, werden sie vermutlich erst richtig stinkig.\n\nIhr wollt Eure Freunde beschützen? Ihr wollt dafür sorgen, dass die Einheimischen besser gestimmt sind? Tja, dann wäre es wohl am besten, wenn sich hier deutlich weniger Düsternisverschmolzene herumtreiben würden. Falls Ihr versteht, was ich meine.", sourceObjective = "Tötet 12 Düsternisverschmolzene im Hintertürpark.", progress = "Das sollte heißen, tötet ein paar Düsternisverschmolzene, damit sie nicht Eure Freunde töten. Ist das eindeutig genug für Euch?", completion = "Saubere Arbeit. Die Bilgewassergoblins können etwas beruhigter schlafen, und vielleicht war das auch Genugtuung dafür, was man ihrem alten Boss angetan hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[85944] = { id = 85944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebenjob: Blutgruppe", description = "Die Düsternisverschmolzenen haben in den Schallenden Tiefen alle möglichen fragwürdigen Forschungen betrieben. Und so ziemlich überall sonst.\n\nNun, sie mussten einiges davon aufschreiben. Schnappt Euch alle Notizen, die Ihr finden könnt und bringt sie zu mir.\n\nSeht mich nicht so an. Mit Plagiarismus hat das nichts zu tun. Das ist reine Industriespionage!", sourceObjective = "Sammelt 8 Forschungsnotizen der Düsternisverschmolzenen in den Zuckenden Feldern.", progress = "Habt Ihr die Waren?", completion = "Nicht schlecht, Aushilfe. Aber erwartet kein Trinkgeld oder sonst irgendwas.", sourceObjectiveStatus = "unverified-source-field" }
quests[85945] = { id = 85945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebenjob: Blut-Ex", description = "Habt Ihr eine Ahnung, wie schwer es ist, getrocknete Blutflecken aus der Kleidung zu bekommen? Nun, ich denke, die habt Ihr.\n\nDie besten Leute des Dampfdruckkartells arbeiten an einem neuen Waschmittel, das auf dieses ernste Problem spezialisiert ist!\n\nUnd obwohl die Blutfelder in den Schallenden Tiefen schlecht für die Umwelt sind - und für Euch - sind sie der perfekte Ort, um unsere neueste Formel zu testen.\n\nWascht den Blutschleimen da draußen ordentlich den Kopf und berichtet uns, was passiert.", sourceObjective = "Testet das Blut-Ex an 8 Blutschleimen in den Zuckenden Feldern.", completion = "Irgendwelche Nebenwirkungen vom Kontakt? Falls ja, habt Ihr dafür ja eine Verzichtserklärung unterschrieben!", sourceObjectiveStatus = "unverified-source-field" }
quests[85946] = { id = 85946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Krabbenausbruch" }
quests[85947] = { id = 85947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine ursprüngliche Reise durch die Zeit", description = "Alte Krieger erzählen immer wieder Geschichten, wie viel schwerer sie es zu ihrer Zeit auf Azeroth hatten.\n\nIch wette, sie würden behaupten, dass Ihr nicht einmal 10 Minuten in ihrer Welt durchhalten würdet.\n\nSeid Ihr zäh genug, um es herauszufinden? Zeigt es mir doch bitte.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ihr habt es geschafft, {name}! Diesen alten Kriegern habt Ihr gezeigt, dass Azeroth immer noch in guten Händen ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[85948] = { id = 85948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine brennende Reise durch die Zeit", description = "Der gleißende Stern wirft sein Licht auf das Land und lässt die Erde verdorren und ganze Landschaften versengen. Es ist ein gnadenloser, fast schon bösartiger Stern. Unter seinem Einfluss eröffnen sich neue Wege... zu weit entfernten Orten und sogar zu weit entfernten Zeiten. Kein Weiser ist in der Lage, die Bedeutung dieses Zeichens vollständig zu verstehen, aber das Glück ist mit den Mutigen.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ah, {name}. Ihr seid zurück. Euch umgibt wahrlich eine Aura aus einer anderen Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[85949] = { id = 85949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine eiskalte Reise durch die Zeit", description = "Der kalte Stern wirft sein frostiges Licht auf das Land und selbst die Schatten ziehen sich zurück. Es ist ein Stern wie kein zweiter, der alle Wärme und Leben entzieht. Unter seinem Einfluss eröffnen sich neue Wege... zu weit entfernten Orten und sogar zu weit entfernten Zeiten. Kein Weiser ist in der Lage, die Bedeutung dieses Zeichens vollständig zu verstehen, aber das Glück ist mit den Mutigen.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ah, {name}. Ihr seid zurück. Eine Kühle umgibt euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[85950] = { id = 85950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tal der Ehre" }
quests[85951] = { id = 85951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tal der Geister" }
quests[85952] = { id = 85952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tal der Weisheit" }
quests[85953] = { id = 85953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gasse" }
quests[85960] = { id = 85960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebenjob: In der Soße verschollen", description = "Einige der Arbeiter, die von den Düsternisverschmolzenen zur Arbeit in den Blutfeldern hergeschafft wurden, sind nie zurückgekommen.\n\nWir haben Berichte erhalten, dass sie in einem gewissen \"Ungehörigen\" verschwunden sind. Scheinbar hat es etwas mit den großen Blutpfützen zu tun?\n\nKlingt nach einem Job für jemanden, der entbehrlicher ist - ich meine erfahrener, als ich.", sourceObjective = "Rettet 8 verschollene Goblins aus dem Ungehörigen in den Zuckenden Feldern.", completion = "Nicht schlecht, auch wenn sie scheinbar einige Schrauben locker haben, wenn Ihr wisst, was ich meine.\n\nDafür muss ich Euch einige Goldmünzen abziehen. Beschädigte Lieferung und so.", sourceObjectiveStatus = "unverified-source-field" }
quests[85961] = { id = 85961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zug der Bauern", description = "Es gibt nordwestlich von hier eine kleine Insel, die Zo'Shuulwarte. Meine Späher haben nach einem Weg in Manaschmiede Omega gesucht, wo wir die Rückkehr des alles Verschlingenden abwenden müssen.\n\nMit etwas Glück haben die Späher bereits einen sicheren Weg ins Innere gefunden.", sourceObjective = "Trefft den Raumgänger bei der Zo'Shuulwarte.", completion = "Hoffentlich haben meine Späher einen sicheren Weg ins Innere der Manaschmiede gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[85962] = { id = 85962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebenjob: Ungehörige Reagenzien", description = "In den Schallenden Tiefen gehen die merkwürdigsten Dinge vor, dank dem Schwarzblut, das es dort noch gibt.\n\nUnd wo es Wahnsinn und Mutationen gibt, sind die Möglichkeiten endlos!\n\nSchafft Euch da raus und sammelt alle grässlichen aber potenziell lukrativen Reagenzien ein, die Ihr finden könnt.", sourceObjective = "Sammelt 10 ungehörige Geschwüre in den Zuckenden Feldern.", progress = "Versucht, erst nach der Lieferung verrückt zu werden, ja?", completion = "Ich bin sicher, die Jungs von Forschung und Entwicklung können damit etwas anfangen... was auch immer das ist.\n\n...Hört Ihr auch ein Flüstern?", sourceObjectiveStatus = "unverified-source-field" }
quests[86151] = { id = 86151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesichtslosenmaske der Verbrannten Brücke", description = "Eine Kriegerin in fremder Umgebung hat keinen festen Stand, insbesondere dann, wenn sie aus ihrer Heimat vertrieben wurde. Die Leere macht diese Unsicherheit zur Realität, bei der ein falscher Schritt in den Abgrund führt oder Eure Seele ausbluten lässt.", sourceObjective = "Bringt die Gesichtslosenmaske der Verbrannten Brücke in einer verstörenden Vision zum Altar zurück.", progress = "Legt die Gesichtslosenmaske der Verbrannten Brücke auf den Altar.", completion = "Der tückische Pfad der Verbrannten Brücke steht Euch offen, wenn Ihr es wagen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[86152] = { id = 86152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesichtslosenmaske des Waghalsigen", description = "Der Jäger wollte nie anführen, jedoch suchte er unablässig nach Herausforderungen. Er führte seine Verbündeten mit geschickter Hand und scheute sich nicht, im Nahkampf sein eigenes Leben zu riskieren. Das Können, das er zeigte, machte ihn genau wie meine anderen Diener noch tödlicher. Bringt diese Maske zurück zum Altar des Waghalsigen, um Eure eigene Entschlossenheit im Kampf zu testen, während die Angriffe Eurer Feinde noch tiefere Wunden schlagen.", sourceObjective = "Bringt die Gesichtslosenmaske des Waghalsigen in einer verstörenden Vision zum Altar zurück.", progress = "Legt die Gesichtslosenmaske des Waghalsigen auf den Altar.", completion = "Der Pfad des Waghalsigen steht Euch offen, wenn Ihr es wagen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[86153] = { id = 86153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesichtslosenmaske der Finsteren Vorstellungen", description = "Diese Magier entstellen ihre Magie, um die Welt zu manipulieren und zu erobern. In der Hoffnung auf größere Macht wandeln sie auf den Pfaden des Reichs der Leere. Bei diesen Unterfangen haben die Magier herausgefunden, dass die wahrhaft dunklen und schrecklichen Dinge in den Tiefen der eigenen Vorstellung verborgen liegen.", sourceObjective = "Bringt die Gesichtslosenmaske der Finsteren Vorstellungen in einer verstörenden Vision zum Altar zurück.", progress = "Legt die Gesichtslosenmaske der Finsteren Vorstellungen auf den Altar.", completion = "Die Gefahren aus den dunklen Winkeln Eures Verstandes werden sich jetzt manifestieren, wenn Ihr es wagen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[86154] = { id = 86154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesichtslosenmaske des Leidenden", description = "Das Handeln mit Geheimnissen, das Handeln mit Lügen und das Wandeln am Rande der Schatten sind die Fähigkeiten des Spionagemeisters. Seine Leidenschaft und all seine Lieben sind seiner Loyalität zur Krone zum Opfer gefallen. Nichts ist mehr übrig, nichts als der Schmerz. Schmerz ist ein fähiger Lehrer und ein Werkzeug, mit dem sich die Leere genau auskennt. Bringt meine Maske zurück, wenn Ihr es wagen wollt, die verschiedenen Formen des Leides zu ertragen.", sourceObjective = "Bringt die Gesichtslosenmaske des Leidenden in einer verstörenden Vision zum Altar zurück.", progress = "Legt die Gesichtslosenmaske des Leidenden auf den Altar.", completion = "Mein Wahnsinn und meine Qual sind wohl noch nicht genug für Euch. Dann setzt Euch in Zukunft gerne noch mehr Leid aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[86155] = { id = 86155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesichtslosenmaske der Langen Nacht", description = "Das Durchhaltevermögen, das nötig ist, um so weit zu kommen, ist wirklich außerordentlich und die Eigenschaft eines wahrhaft erfahrenen Abenteurers. Die längste Nacht ist jetzt ganz nahe, und mit ihr kommt die ultimative Herausforderung. Diejenigen, die das Kommen des ewigen Zwielichts verhindern wollen, kämpfen einen sinnlosen Kampf. In der längsten Nacht werden sie ewig am Rande des Wahnsinns bleiben.", sourceObjective = "Bringt die Gesichtslosenmaske der Langen Nacht in einer verstörenden Vision zum Altar zurück.", progress = "Legt die Gesichtslosenmaske der Langen Nacht auf den Altar.", completion = "Mit einem Schritt in Richtung der längsten Nacht werdet Ihr den Verstand sehen, den Ihr bereits verloren habt. Wollt Ihr den Rest in solch einem nutzlosen Unterfangen auch noch riskieren?", sourceObjectiveStatus = "unverified-source-field" }
quests[86156] = { id = 86156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitmischen", description = "Ihr da. Macht das noch einmal. Könnte gutes Zeug sein, das wir noch nicht gesehen haben.\n\nMacht diese Höhlen auf und seht Euch an, was drin ist!", sourceObjective = "Tragt 10-mal zu Ereignissen auf der Schlachtkarte der Sireneninsel bei und schließt ein Ereignis ab, indem Ihr das Ziel ausschaltet.", progress = "Habt Ihr Euch die Höhle angesehen? Nein? Dann los!", completion = "Das war einfach. Sollten wir öfter machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[86174] = { id = 86174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spezialauftrag: Aufziehender Sturm" }
quests[86177] = { id = 86177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebenjob: Die Gaben der Gezeiten", description = "Ihr seht aus wie jemand, der keine Scheu hat, sich die Hände schmutzig zu machen. Lust auf eine kleine Schatzsuche?\n\nUnweit der Kaja'Küste soll ein Schiff explodiert sein. Geht zum Ufer und seht nach, was die Flut angespült hat.\n\n\"Wer's findet, darf's behalten\" ist schließlich eine Maxime der Goblins.", sourceObjective = "Sammelt 5 glänzende Schätze an der Kaja'Küste.", progress = "Bringt Eure eigene Schaufel mit. Ich stelle nie was zur Verfügung. Ist nur ein unnötiges Haftungsrisiko.", completion = "Wenn das mal keine fette Beute ist!\n\nKeine Sorge, Ihr bekommt schon Euren Anteil.", sourceObjectiveStatus = "unverified-source-field" }
quests[86178] = { id = 86178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebenjob: Küstensäuberung", description = "Es wird Zeit, dass die Venture Company etwas mehr an Wohlwollen gewinnt.\n\nWir wollen einige effiziente Arbeiter wie Euch anheuern, um die Kaja'Küste aufzuräumen.\n\nKönntet Ihr uns helfen, einige der Kaja'mentare zu töten, die am Strand außer Rand und Band sind? Ihr sollt auch konkurrenzfähig entlohnt werden.", sourceObjective = "Tötet 10 aufgebrachte Kaja'mentare an der Kaja'Küste.", completion = "Danke für die Hilfe.\n\nEinfache Arbeit, einfacher Profit.", sourceObjectiveStatus = "unverified-source-field" }
quests[86179] = { id = 86179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebenjob: Großer Durchbruch für Glücksmoment", description = "Schonmal von den Glücksmomentminen drüben an der Kaja'Küste gehört? Die wurden etwas übereilig eingerichtet. Die Düsternisverschmolzenen haben der Venture Company nicht gerade viel Zeit gegeben, den Ort auszubauen.\n\nLange Rede, kurzer Sinn: Es ist gut möglich, dass die Minen einstürzen, wenn wir nicht Hand anlegen. Das wären keine guten Neuigkeiten. Für niemanden, besonders nicht für meinen Geldbeutel.\n\nKönntet Ihr da vorbeischauen und in den Minen einige Stützbalken anbringen? Das sollte vorerst genügen.", sourceObjective = "Platziert 6 Stützbalken in den Glücksmomentminen an der Kaja'Küste.", completion = "Das sollte uns etwas Zeit verschaffen.\n\nGute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[86180] = { id = 86180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebenjob: Verseuchte Gewässer", description = "Also, meine Arbeiter sollten drüben in Zuldazar eigentlich etwas Kaja'mit aufladen, aber anscheinend ist der Transporter umgekippt, woraufhin ein Hai die gesamte Ladung verschluckt hat.\n\nIch wollte einen Versicherungsanspruch einreichen, aber die glauben mir einfach nicht. Es bleibt uns also keine andere Wahl, als das Kaja'mit selbst zurückzuholen.\n\nWärt Ihr für eine kleine Haijagd zu haben?", sourceObjective = "Holt das verschluckte Kaja'mit von dem kaja'tragenden Messerrachen an der Kaja'Küste zurück.", progress = "Glaubt Ihr, dass der Hai am Ende noch reden kann? Ein sprechender Hai wäre doch witzig, oder?", completion = "Schöne Nummer, {name}. Das ist jede Menge weniger Papierkram, um den ich mich jetzt kümmern muss.\n\n...Ihr habt das Kaja'mit abgewaschen, nachdem Ihr den Hai ausgenommen habt, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[86182] = { id = 86182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisterjäger", description = "Ich habe an der Oasenkonsole gearbeitet und glaube, bereit für den nächsten Schritt zu sein. Es geht um Zerstörung, daher musste ich direkt an Euch denken.\n\nIhr müsst den Phasenleiter verwenden, um in den ungebundenen Raum von K'aresh zu wechseln und die Essenz der geisterhaften Schieferrücken zu bergen. Ich erkläre mehr, wenn Ihr zurück seid.", sourceObjective = "Sammelt 10 Schieferrückenessenzen im ungebundenen Raum von K'aresh.", progress = "Und? Hattet Ihr Erfolg?", completion = "Ausgezeichnet.\n\nUnd jetzt erwecken wir die Toten zum Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[86183] = { id = 86183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Götter", description = "Heute erschaffen wir Leben. \n\nSofern meine Berechnungen stimmen, - und davon gehe ich aus - können wir die von Euch gesammelte Essenz zusammen mit den gewonnenen Daten nutzen, um neue Schieferrücken zu erschaffen.", sourceObjective = "Helft Ve'nari dabei, mit ihrer Maschine Leben in der Oase zu erschaffen.", completion = "Gut gemacht, {name}. Das gab es so noch nie.", sourceObjectiveStatus = "unverified-source-field" }
quests[86184] = { id = 86184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleinere Probleme", description = "Die Maschine ist zwar nützlich, doch die Schieferrücken müssen anfangen, sich zu vermehren, um sich selbst erhalten zu können. Bislang machen sie keine Anstalten in der Hinsicht.\n\nNehmt dieses Gerät und sammelt damit Schieferrücken für eine Untersuchung. Om'talad wird die Daten prüfen.", sourceObjective = "Schrumpft und sammelt 10 Schieferrückenstreuner.", progress = "Habt Ihr die angeforderten Schieferrücken mitgebracht?", completion = "Danke. Die Daten, die wir daraus erhalten, werden von unschätzbarem Wert sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[86185] = { id = 86185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freilauf", description = "Ich habe mit Ve'nari und Om'talad gesprochen. Sie wollen die Schieferrücken wieder zusammenbringen.\n\nAnscheinend haben Schieferrücken ihre Fruchtbarkeit früher bei gemeinsamen Wettrennen zur Schau gestellt.\n\nFordert den Schieferrückenalpha zu einem Rennen heraus. Im schlimmsten Fall bekommt Ihr beide etwas Bewegung. Doch wenn alles gut läuft, erhöhen wir unsere Chance auf eine erfolgreiche Paarung.", sourceObjective = "Fordert den Schieferrückenalpha zu einem Wettrennen heraus.", progress = "Wie läuft das Rennen?", completion = "Ah! Was für ein gutes Rennen, {name}!\n\nDrücken wir die Daumen. Vielleicht hilft es ja.", sourceObjectiveStatus = "unverified-source-field" }
quests[86186] = { id = 86186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Supernase", description = "Es scheint, als würden die Schieferrücken nicht die richtigen Pheromone ausstoßen, was sie daran hindert, sich zu paaren. \n\nWir glauben, dass es sich um eine Nebenwirkung der Stasis handelt. Die Technologie wurde nie für so lange Zeiträume getestet. Bis jetzt. \n\nHemet hat mir erzählt, dass es in Azeroth Kreaturen namens Niffen gibt, die auf diese Forschung spezialisiert sind. Bringt mir einen dieser Niffen aus Azj-Kahet. Ihr könnt mein Portal verwenden, um dort schnell hinzugelangen.", sourceObjective = "Reist nach Mmarl in Azj-Kahet und findet einen Niffen, der gewillt ist, in der Oase zu helfen.", progress = "Ihr riecht von oben nach unten nach Chancen!", completion = "Gut gefeilscht! Lasst uns diese Transaktion in die Wege leiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[86187] = { id = 86187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der kleinstmögliche Aufwand", description = "Ihr seid wahrlich geschickt im Feilschen, {name}. Es war mir ein Vergnügen! Ich beginne schon mal mit dem Packen, während Ihr mir ein paar Käferteile beschafft, in Ordnung?", sourceObjective = "Sammelt 50 Käferteile in Rak-ush und der näheren Umgebung.", progress = "Hattet Ihr Erfolg?", completion = "Schau an! Genau das, was ich wollte. Ich hoffe, das war nicht allzu beschwerlich für Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[86188] = { id = 86188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Pilzweg", description = "Der arme Gharrli muss versorgt werden, während ich weg bin. Die Pilze, die Ihr besorgt, helfen dabei.\n\nBeschafft erst mal acht. Um den letzten kümmern wir uns später!", sourceObjective = "Sammelt 8 Rak-Ushpilze in Rak-ush und der näheren Umgebung.", progress = "Habt Ihr die Pilze bekommen?", completion = "Schön. Schön!", sourceObjectiveStatus = "unverified-source-field" }
quests[86189] = { id = 86189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilzinvasion", description = "Ich schicke Euch an einen wahrlich furchterregenden Ort, doch gewiss seid Ihr imstande, mit allem fertig zu werden, was Euch dort begegnet!\n\nWärt Ihr so gütig, einige der Kreaturen dort zu beseitigen, damit es Gharrli künftig leichter fällt, die Zutaten zu beschaffen?", sourceObjective = "Tötet 10 Monster im Stütznest Vosh.", completion = "Ich komme zwar gut mit Nerubern klar, aber diese Viecher...\n\nVor denen habe ich Angst. Gut, dass sie weg sind. Puh!", sourceObjectiveStatus = "unverified-source-field" }
quests[86190] = { id = 86190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Pilz, sie zu knechten", description = "Wir arbeiten an einem neuen Duft, der die Einheimischen erfreuen soll, aber uns fehlt noch eine Zutat.\n\nEs handelt sich dabei um einen seltenen Pilz aus dem Stütznest Vosh. Besorgt ihn, damit Gharrli den Duft in meiner Abwesenheit fertigstellen kann.", sourceObjective = "Beschafft einen Voshpilz aus dem Stütznest Vosh.", progress = "Habt Ihr den Pilz?", completion = "Oooooh ja! Das ist es. Genau dieser Duft wird alles revolutionieren! Großartige Arbeit, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[86191] = { id = 86191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir riechen uns später", description = "Nun. Das wäre alles, denke ich. Ich bin bereit für ein Abenteuer!", sourceObjective = "Trefft Rhubarn und Ve'nari in der Oase von K'aresh.", completion = "Ihr habt mir einen höchst... ungewöhnlichen Freund mitgebracht, {name}. Seltsam, aber reizend.", sourceObjectiveStatus = "unverified-source-field" }
quests[86192] = { id = 86192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Knochen gebettet", description = "Ich sprach eben mit Om'talad. Anscheinend sammelten Schieferrücken einst Knochen für ihre Geburtsnester, was in Anbetracht ihrer pflanzlichen Ernährung recht kurios ist! \n\nFür gewöhnlich finden sie die Knochen von toten Tieren, doch in den Biokuppeln haben wir keine. Könnt Ihr mir Knochen von Kreaturen außerhalb der Oase besorgen? Sie würden sich freuen, und ich auch!", sourceObjective = "Sammelt 8 Knochen von Kreaturen aus der Umgebung von K'aresh und türmt sie in der Oase zu einem Haufen auf.", progress = "Habt Ihr die gewünschten Nester gebaut?", completion = "Danke, {name}. Wie das gemütlich sein kann, ist mir schleierhaft, aber ich bin ja auch kein Schieferrücken.", sourceObjectiveStatus = "unverified-source-field" }
quests[86193] = { id = 86193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leben für Leben", description = "Wir sind zu spät! Das Ritual hat seine eigene Dynamik entwickelt. Es wird immer mehr Energie anziehen, bis die Maschine überlädt. Tazavesh, die Biokuppeln... nichts wird sicher sein, wenn sich dieser Defekt ausbreitet.\n\nWenn wir die Infusoren entfernen, sollte sich die Energie verflüchtigen, bevor sie Schaden anrichten kann. Doch sie sind stark. Sie reißen Euch in Stücke, solltet Ihr ihnen zu nahekommen, und allein habe ich nicht die Kraft...\n\nBindet mich los. Dann hülle ich Euch in meine Energie. Das sollte ausreichen, um Euch in die Nähe der Maschine zu bringen.", sourceObjective = "Haltet die Maschine auf.", completion = "Geht es Euch gut? Ich habe versucht, Euch zu beschützen.\n\n<Om'taha flackert in Eurer Sicht auf und verschwindet wieder.>\n\nEntschuldigt. Das hat mich viel gekostet. Ich brauche einen Moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[86194] = { id = 86194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Duft der Liebe", description = "Ich war unterwegs, um nach Euren Schieferrücken zu schauen. Eure Mittlerfreunde lagen falsch!\n\nSie verströmen den Duft der Liebe, er ist nur nicht stark genug, um diese trockene Luft von K'aresh zu durchdringen. Zumindest noch nicht! Ich habe ein paar Pheromone zusammengepanscht. Die sollten Abhilfe schaffen.\n\nNehmt diese Sprühflasche und sprüht damit die Schieferrücken ein. Das wird die Sache anheizen!", sourceObjective = "Tränkt 12 Schieferrückenstreuner mit Pheromonen.", progress = "Habt Ihr sie mit dem Duft besprüht?", completion = "Habt ein wenig Geduld, {name}. Liebe braucht Zeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[86195] = { id = 86195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schießerrücken", description = "Oje. Ich hätte nicht gedacht, dass ich das einmal erleben würde. Ein frisch geborener Schieferrücken!\n\nIch habe die standardmäßigen, nichtinvasiven medizinischen Tests vorgenommen. Allerdings muss ich noch sein Koordinationsvermögen überprüfen. Mir ist aufgefallen, dass er immer diesem Ball hinterherjagt. Vielleicht könntet Ihr ihn ja werfen, und beobachten, wie er sich dabei anstellt?", sourceObjective = "Fangt einen Ball 10-mal, während Ihr mit Eurem Schieferrückenjungen spielt.", progress = "Hat das Jungtier auf den Ball reagiert?", completion = "Die Vitalfunktionen sind einwandfrei, und die Koordination ist noch besser, als ich zu hoffen wagte. Ich danke Euch für das Spielen - äh, Testen der Koordination des Jungtieres.", sourceObjectiveStatus = "unverified-source-field" }
quests[86196] = { id = 86196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebt mir Treibstoff", description = "Danke, dass Ihr gekommen seid, {name}.\n\nWir sind beim Versuch, K'aresh zu terraformen, ständig mit Gefahren konfrontiert. Eine der größten ist, dass unsere Kuppeln Kreaturen anziehen, die sie als bequeme Energiequellen ansehen.\n\nBiokuppel Frühlingsbringer ist von ihnen geplagt. Ich habe einen Plan, das in Ordnung zu bringen, aber ich könnte Eure Hilfe bei der Vorbereitung brauchen.", sourceObjective = "Sammelt Feuerblütenpollen für Om'vek.", progress = "Habt Ihr genug Pollen für mich gesammelt?", completion = "Perfekt, {class}. Dank unserer Ausrüstung werden wir die Macht dieser bescheidenen Pflanze freisetzen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[86200] = { id = 86200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht mir Feuer", description = "Jetzt müssen wir diese Feuerblütenpollen zu Treibstoff verarbeiten. Dieser Treibstoff wird das Ende dieser Plagen garantieren.", sourceObjective = "Verarbeitet die Feuerblütenpollen zu Treibstoff.", progress = "Platziert die Feuerblütenpollen einfach in den Behältern auf der Konsole und wir verarbeiten sie zu etwas, das wir gebrauchen können.", completion = "Hervorragend. Ich hoffe, Ihr seid bereit, den Zorn der Mittler auf diese lästigen Kreaturen zu entfesseln.", sourceObjectiveStatus = "unverified-source-field" }
quests[86201] = { id = 86201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käferjagd", description = "Jetzt nachdem wir die Feuerblütenpollen verarbeitet haben, können wir es den Plagen in Biokuppel Frühlingsbringer einheizen.", sourceObjective = "Verwendet den Flammenwerfer, um die vollgefressenen Kriecher von der Kuppel zu vertreiben, und zerstört sie anschließend.", progress = "Habt Ihr die Biokuppel mit der Flamme gereinigt, die ich Euch gegeben habe?", completion = "Die Schildintegrität der Biokuppel kehrt zu ihren normalen Werten zurück. Ich wusste, dass ich mich auf den Hang Eures Volkes zu Feuer verlassen könnte, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[86203] = { id = 86203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Schleuse", description = "Meine Quellen berichten, dass Truppen der Düsternisverschmolzenen die Wasserwerke in den Schallenden Tiefen eingenommen haben. Dort haben sie die Stromgeneratoren unter ihre Kontrolle gebracht und leiten die Elektrizität um.\n\nIch weiß nicht, was sie damit bezwecken, und will es auch gar nicht wissen.\n\nBereitet ihrer Operation ein Ende und Ihr werdet dafür angemessen belohnt.", sourceObjective = "Biergoth möchte, dass Ihr Giesel Gigaschock in Operation: Schleuse besiegt.", progress = "Habt Ihr die Operation beendet?", completion = "Der Ratsvorsteher wird erfreut sein zu hören, dass die Wasserwerke wieder in irdenen Händen sind.\n\nGute Arbeit, Fremdling.", sourceObjectiveStatus = "unverified-source-field" }
quests[86204] = { id = 86204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreiung von Lorenhall: Das Haus verliert", description = "Gallywix ist eine Schande für Lorenhall, seitdem er vergessen hat, woher er kommt.\n\nGallywix hat schon immer den kleinen Mann als Fußabtreter benutzt. Gier und die stete Suche nach der \"nächsten großen Sache\" veranlassen ihn lediglich dazu, noch härter durchzugreifen. Auf der Suche nach Macht, einfach um der Macht willen? Nichts da! Die Macht liegt in den Händen des Volkes.\n\nLegen wir Gallywix schnell das Handwerk, {name}.", sourceObjective = "Besiegt Chromkönig Gallywix in der Befreiung von Lorenhall.", completion = "Ich glaube es nicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[86261] = { id = 86261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimwärts zu sicheren Ufern", description = "<Der verfilzte Hund sieht Euch ins Lager gehen und freut sich, wie es nur ein Hund kann. Er wedelt mit dem Schwanz, als er das vertraute Gesicht jener Person erkennt, die sein Lieblingsspielzeug gefunden hat.\n\nAuf der verblichenen Marke um seinen Hals steht: 'Duke'.\n\nEr scheint seit dem Verschwinden der Kul Tiraner hier zu sein und die zahllosen Gefahren der Insel überlebt zu haben.\n\nDuke sieht Euch sehnsüchtig an und schubst mit der Schnauze liebesbedürftig Eure Hand.>", sourceObjective = "Streichelt den braven Jungen.", progress = "<Der Hund schaut Euch an. Hoffnung leuchtet in seinen alten Augen auf.>", completion = "<Marmaduke scheint die Insel mit Euch verlassen zu wollen, um neue Abenteuer zu erleben.\n\nEr schnappt sich sein Lieblingsspielzeug und wedelt fröhlich mit dem Schwanz.\n\nHoffentlich ist das der Beginn einer neuen Freundschaft.>", sourceObjectiveStatus = "unverified-source-field" }
quests[86271] = { id = 86271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grab der Vernunft", description = "Und noch einer weniger, wie?\n\nIch sag's Euch, diese Schwarzblutausgrabungsstätten verschlucken meine Arbeiter schneller, als ich neue einstellen kann! Jeden Tag geht einer meiner Jungs zitternd zu Boden und faselt was von Tentakeln im Dreck...\n\nBringt sie zu meinem Mann in der Höhle da drüben, Stichdepp. Er arbeitet an irgendeinem \"Heilmittel\".\n\nVielleicht kann er dem armen Kerl helfen.", sourceObjective = "Tragt den handlungsunfähigen Arbeiter in die Höhle in den Schallenden Tiefen.", progress = "Ich bin schon kurz. Kurz davor, den Verstand zu verlieren, weil wir zu wenig Personal haben!", completion = "Das ist heute schon der Dritte.\n\nWird immer schlimmer da draußen.", sourceObjectiveStatus = "unverified-source-field" }
quests[86272] = { id = 86272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzblut entgegenwirken", description = "Schwarzblut? Mieses Zeug. Gut, dass ich die Maske hier habe. Mit dem Zeug sollte niemand zu tun haben.\n\nDas sickert in alle Poren, macht den Kopf ganz kirre. Manchen wird schwindelig, andere sehen Dinge, die es nicht gibt. Manchen wachsen sogar merkwürdige Schuppen. Schon beim Gedanken daran wird mir ganz anders.\n\nEs gibt außerdem kein Heilmittel. Wir können nur die Schmerzen lindern und vielleicht etwas gegen die Symptome tun.\n\nIch habe ein \"Heilmittel\" aufgesetzt. Ist nur Suppe, aber das wissen sie nicht.\n\nIst fast \"fertig\", könnte aber noch etwas Geschmack vertragen.", sourceObjective = "Helft Stichdepp dabei, die Symptome der Goblins in den Schallenden Tiefen zu lindern.", progress = "Der Topf köchelt schon. Es fehlt nur noch das gewisse Etwas.", completion = "Hühnersuppe ist bei vielen Dingen gut. Keine Ahnung, ob das Mundwasser hilft.\n\nWenigstens riechen sie dann etwas besser?", sourceObjectiveStatus = "unverified-source-field" }
quests[86273] = { id = 86273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werkstattbesuch", description = "Das ist alles, was wir für den Moment tun können.\n\nWenn Ihr uns wirklich dabei helfen wollt, das alles wieder hinzukriegen, solltet Ihr mit unserer örtlichen Ingenieurin sprechen... äh, Tricksy... oder war es Trixxy? Trick Siebzehn?\n\nJedenfalls hat sie ihre Werkstatt tiefer in der Höhle eingerichtet, wo Benny sie Tag und Nacht an einer Art... \"dauerhafteren Lösung\" tüfteln lässt.\n\nSie ist ein bisschen seltsam, aber sie hat Köpfchen. Wenn irgendjemand eine Chance hat, den Leuten hier unten zu helfen, dann sie.", sourceObjective = "Findet Trixxie Bolzenschnapps Werkstatt weiter in den Tiefen des Grabs der Vernunft in den Schallenden Tiefen.", completion = "Ey! Seht Ihr nich', dass ich zu tun hab?\n\nWas wollt Ihr denn?", sourceObjectiveStatus = "unverified-source-field" }
quests[86274] = { id = 86274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Automatisierungslösung", description = "Wie Ihr Euch vermutlich bereits gedacht habt, ist es nicht gerade gesund, Schwarzblut ausgesetzt zu sein. Und das ist wiederum ein Problem für unsere Operation.\nWir können nicht ständig unsere Arbeiter ersetzen. Das ist teuer. Und ethisch korrekt ist es auch nicht.\n\nAlso! Was ist die Lösung? Unsere Arbeiter durch vollautomatisierte Bots zu ersetzen.\n\nDiese Schönheiten werden nicht vom Schwarzblut beeinflusst. Sie graben und schleppen... Präzision, Effizienz und keine kranken Arbeiter mehr!\n\nIch brauche nur mehr Schrott, um sie herzurichten. Seid Ihr dabei?", sourceObjective = "Sammelt Metallschrott ein, der in der Höhle in den Schallenden Tiefen verstreut liegt.", progress = "Die Zeit... Ihr wisst, was sie macht.", completion = "Klasse! Damit kriegen wir sie startklar!", sourceObjectiveStatus = "unverified-source-field" }
quests[86275] = { id = 86275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schädlingsbekämpfer gesucht", description = "Nun, wenn Ihr unbedingt helfen wollt...\n\nIn dieser Höhle sind wir vor dem Schwarzblut sicher... Nun, das waren wir zumindest, bevor all diese miesen Blutschmauser aufgetaucht sind.\n\nDiese hässlichen kleinen Viecher hatten schon immer Durst nach Blut... aber jetzt sind die ganz verrückt nach Schwarzblut! Ich vermute, dass sie die Schwarzblutvergiftung verbreiten, wenn sie uns beißen.\n\nIch kann so nicht arbeiten. Immer, wenn ich einen zwischen dem ganzen Schrott sehe, will ich einfach schreien. Sie sind ekelhaft, und ich will nicht gebissen werden und plötzlich irgendwelche Dinge sehen.\n\nZerstampft sie, damit wir unbesorgt weiterarbeiten können!", sourceObjective = "Tötet Blutschmauser in der Höhle in den Schallenden Tiefen.", completion = "Würg! Ekelhaft, aber effektiv. Jetzt kann ich mich wieder an die Arbeit machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[86276] = { id = 86276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draußen auf den Feldern", description = "Wenn Trixxie die Bots fertig hat, müssen wir nur noch markieren, wo sie sich an die Arbeit machen sollen.\n\nGeht da raus, feuert eine Signalpistole ab und stationiert diese Blechbüchsen... Dann schaut Ihr nach, ob sie auch wirklich, Ihr wisst schon, funktionieren.\n\nSchaut nach fehlerhaften Servos, rauchenden Kühlschlitzen... Ihr versteht schon.\n\nWenn sie mit der Arbeit anfangen? Klasse.\n\nWenn nicht... Nun, dann muss ich wohl wieder ein paar Arbeiter reinschicken, um aufzuräumen.", sourceObjective = "Stationiert Goblinbots in den Zuckenden Feldern in den Schallenden Tiefen.", completion = "Sie haben funktioniert? Ich meine, natürlich haben sie das!", sourceObjectiveStatus = "unverified-source-field" }
quests[86277] = { id = 86277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nie wieder \"Wurmfutter\"", description = "Die Bots arbeiten im Feld, doch da draußen sind auch immer noch Arbeiter aus Fleisch und Blut.\n\nDie müssen sicher zurückgelangen. Und das können sie nicht, solange dieser geifernde \"Wurm\" ihnen an den Hacken klebt, weil er auf den Geschmack von Goblinfleisch gekommen ist.\n\nAlso, der Plan geht folgendermaßen: Ich will das Vieh nicht vertreiben, ich will, dass es ein für alle Mal weg ist. Geht da raus, macht diesen übergroßen \"Regenwurm\" ausfindig und stellt sicher, dass er das Zeitliche segnet.\n\nHaltet Euch nicht zurück... Ich will, dass seine Eingeweide die Felder schmücken. Rache für all die Goblins, die er verputzt hat.", sourceObjective = "Tötet den irrsinnigen Augenstiel in den Zuckenden Feldern in den Schallenden Tiefen.", completion = "Woah, wie ich sehe, habt Ihr Euch meine Worte zu Herzen genommen!\n\nAber denkt daran, eine Dusche zu nehmen, nachdem Ihr hier fertig seid, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[86297] = { id = 86297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Führung bedingt Arbeitsmoral", description = "Lorenhall verschluckt alles, was gut ist. Jetzt hat es auch Laslo erwischt. Wir müssen rausfinden, wer jetzt das Sagen hat, und wie wir alle beschützen. Ich habe eine Idee, wo wir zuerst fragen.", sourceObjective = "Findet den Goblin, der für das Bilgewasserkartell in Lorenhall verantwortlich ist.", completion = "Wenigstens ist fürs Erste kein einzelner Goblin das nächste Ziel von Gallywix. So haben wir Zeit, uns um das Schwarzblut zu kümmern. Und anschließend überlegen wir, wie wir mein Volk aus der Fuchtel von Gallywix befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[86305] = { id = 86305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käferjagd" }
