quests[86321] = { id = 86321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Tür zu Tür" }
quests[86327] = { id = 86327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sturmfelder", description = "Diese Ödnisbewohner haben das Band des Mittlers. Wir müssen es zurückholen, sonst werdet Ihr nie zu Dimensius gelangen.\n\nEs ist köstlich, wie blutrünstig sie sind. Wir sollten sie für unsere Sache gewinnen. Wir werden für die kommende Schlacht eine Armee benötigen und sie haben die Zahlen dafür.\n\nDas Leerenglas liegt zwischen ihrem Lager und uns. Das sollte uns eine Gelegenheit bieten, sie zu manipulieren... Sprecht mit den Ödnisbewohnern.", sourceObjective = "Trefft Xal'atath in den Sturmfeldern.", completion = "Die Aura von Dimensius reißt die Überreste K'areshs in Stücke. Bald wird er verschlingen, was immer von dieser kleinen Welt übrig ist.\n\nUns bleibt Stunde um Stunde weniger Zeit, ihn aufzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[86332] = { id = 86332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energieverteilung", description = "Mein Volk braucht Energie zum Leben. Wir können sie von den Pylonen ernten, die wir aufgestellt haben, um sie zu sammeln. Wir können sie aber auch von Plünderern jagen, die sich genommen haben, was unser ist.\n\nNehmen wir uns die magere Ausbeute des heutigen Tages und verteilen sie unter meinen Leuten. Wenn wir gemeinsam in den Krieg ziehen wollen, wird es uns beiden helfen, den Charakter Eurer Verbündeten zu kennen.", sourceObjective = "Sammelt und verteilt Energie im Lager der Ödnisbewohner und der näheren Umgebung.", progress = "In der gnadenlosen Ödnis K'areshs dreht sich alles ums Überleben. Wir nehmen, was wir brauchen, um unsere Zukunft zu sichern.", completion = "Eure Hilfe bleibt nicht unbemerkt. Mein Volk überlebt dank der Energie in diesen Kisten einen weiteren Tag... und hoffentlich noch viele mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[86339] = { id = 86339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oasenturbogang", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[86340] = { id = 86340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oasenturbogang - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[86341] = { id = 86341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oasenturbogang - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[86342] = { id = 86342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segeln über K'aresh", description = "Wir sind mit den K'arrocs außerhalb der Oase herumgeflogen. Vielleicht hättet Ihr ja auch Lust, auf einem zu reiten?", sourceObjective = "Schließt das Rennen \"Oasenturbogang\" ab.", completion = "Hervorragend. Euch auf dem K'arroc da draußen herumfliegen zu sehen, war ein Anblick für die Götter.\n\nIhr könnt wirklich gut reiten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[86348] = { id = 86348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fuchsbann", description = "Ihr habt Euch gut um die Schieferrücken gekümmert. Würdet Ihr das auch für die Dornschweife tun?\n\nFür ihre Vermehrung benötigen wir ein wenig ihrer Astralessenz. Beschafft sie mir.", sourceObjective = "Sammelt 10 Dornschweifessenzen beim Phasentauchen im ungebundenen Raum auf K'aresh.", progress = "Habt Ihr die Essenzen?", completion = "Auf Euch ist immer Verlass.", sourceObjectiveStatus = "unverified-source-field" }
quests[86349] = { id = 86349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schoßkäferessenzjäger", description = "Dornschweife jagen Kleintiere. Für ihre Vermehrung sollten wir auch dafür sorgen, dass die Schoßkäferpopulation wächst.\n\nSammelt ein wenig ihrer Astralessenz. Ihr könnt auch mit einem Phasenleiter in den ungebundenen Raum gelangen.", sourceObjective = "Sammelt 10 Schoßkäferessenz im ungebundenen Raum von K'aresh.", progress = "Wie steht es um Eure Bemühungen?", completion = "Ausgezeichnet. Ich übernehme ab hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[86350] = { id = 86350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eau de Fuchs", description = "Da ist ja mein allerliebster {race}! \n\nIch habe in der Oase herumgeschnuppert und eine Mischung aus Pheromonen für die Dornschweife kreiert. Könnt Ihr sie ordentlich damit einsprühen?\n\nLasst Om'talad wissen, wenn Ihr fertig seid - er wollte ebenfalls ein paar Tests durchführen!", sourceObjective = "Besprüht 8 königliche Dornschweife mit Pheromonen.", progress = "Habt Ihr die Pheromone aufgebracht?", completion = "Ah, ich bin Euch für Eure treue Unterstützung dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[86351] = { id = 86351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werft Euch in Pose", description = "Uns geht langsam das Dornschweiffutter aus. Seltsam, eigentlich sollten sie den Großteil ihrer Nahrung selbst jagen.\n\nKönntet Ihr vielleicht zu Dokumentationszwecken ein paar Fotos von ihnen machen? Möglicherweise hilft uns das, die Ursache zu finden.", sourceObjective = "Dokumentiert 10 königliche Dornschweife.", progress = "Habt Ihr die Fotos gemacht?", completion = "Sie gehen überhaupt nicht auf die Jagd? Das ist inakzeptabel. Wir müssen schleunigst eine Lösung finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[86352] = { id = 86352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd nach einem guten Autoren", description = "Ich mache mir langsam Sorgen, dass wir das Ökosystem aus dem Gleichgewicht bringen könnten. Wir brauchen einen Berater.\n\nHabt Ihr das Buch \"Die Grünen Hügel des Schlingendorntals\" gelesen? Ich fand es sehr gut. Der Autor scheint vom Jäger zum Naturschützer geworden zu sein. Fragt lieber nicht, woher ich diese Informationen habe.\n\nDas sind aber genau die beiden Fähigkeiten, die ich brauche. Holt ihn her. Mein letzter Stand ist, dass er sich im Azurblauen Gebirge auf den Dracheninseln aufhält. Nutzt das Portal, um dorthin zu reisen.", sourceObjective = "Sucht im Azurblauen Gebirge auf den Dracheninseln nach Hemet Nesingwary.", completion = "Wenn Ihr meine Hilfe wünscht, benötige ich zunächst Eure.", sourceObjectiveStatus = "unverified-source-field" }
quests[86353] = { id = 86353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jugendschutz", description = "Diese Gnolle haben Kinder aus Iskaara entführt. Ich wollte mich eigentlich reinschleichen und sie befreien, aber dabei könnte ich etwas Hilfe gebrauchen.\n\nTeilen wir uns auf. Zwei Augenpaare sind besser als eines. Falls Ihr irgendwelche Kinder seht, sagt ihnen, dass sie hierherkommen sollen. Sagt, Hemet schickt Euch. Sie kennen mich.", sourceObjective = "Befreit 6 Tuskarrkinder aus dem Brackenfellgestrüpp.", completion = "Gut gemacht, {name}.\n\nIch muss gestehen, ich war froh, dass Ihr aufgetaucht seid. Ich weiß nicht, ob ich das alleine geschafft hätte.", sourceObjectiveStatus = "unverified-source-field" }
quests[86354] = { id = 86354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein einschlagendes Gegenmittel", description = "Diese Gnolle sind eine wahre Landplage. Sie werden zu groß und bringen das Ökosystem aus dem Gleichgewicht.\n\nWir müssen sie stoppen, damit sich dieses Land von all dem Verfall erholen kann.", sourceObjective = "Tötet Gnolle und ihre Diener im Brackenfellgestrüpp und dessen Umgebung.", progress = "Das Töten bereitet mir zwar keine Freude, aber es muss sein.", completion = "Wir haben die Verderbnis hier entfernt. Mit der Zeit wird sich das Land erholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[86355] = { id = 86355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwertung des kompletten Tiers", description = "K'aresh, was? Klingt ein wenig nach Nethersturm.\n\nIch habe eine Weile bei den Tuskarr gelebt und viel von ihnen gelernt. Ich sollte eigentlich Fleisch für das Abendessen besorgen. Wenn Ihr das erledigen könnt, fange ich mit dem Packen an.", sourceObjective = "Beschafft 20 Stücke Brüffelchfleisch aus dem Azurblauen Gebirge.", progress = "Verwertet das komplette Tier. Dann geht es schneller.", completion = "Davon sollte das ganze Dorf satt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[86356] = { id = 86356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachhaltige Verwertung", description = "Ich möchte mich für die Gastfreundschaft der Tuskarr revanchieren. Bei ihnen stehen einige Reparaturen an.\n\nKönnt Ihr etwas Holz für sie sammeln? Sie können die Reparaturen selbst durchführen, brauchen aber etwas Hilfe beim Zusammentragen des Materials.", sourceObjective = "Sammelt 12 Stücke gehacktes Holz im Azurblauen Gebirge.", progress = "Habt Ihr das Holz?", completion = "Das sollte für alle ihre Vorhaben ausreichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[86357] = { id = 86357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit für Leckerlies", description = "Die heimischen Ottuks leben mit den Tuskarr in Symbiose und es ist Fütterungszeit.\n\nKönntet Ihr ein paar der Fleischstücke für sie auslegen, die Ihr besorgt habt?", sourceObjective = "Platziert einen Fleischhaufen für die hiesigen Ottuks am Rande von Iskaara.", completion = "Gut gemacht! Ein voller Bauch sollte sie zufrieden stimmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[86358] = { id = 86358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausreden über Ausreden", description = "Jetzt kommt die Königsdisziplin für Euch!\n\nDie kleinen Ottuks müssen handzahm werden. Geht hin und krault sie mal ordentlich.\n\nMühsame Arbeit, doch sie muss getan werden.", sourceObjective = "Streichelt 5 Ottukjunge am Rande von Iskaara.", completion = "Ich danke Euch, dass Ihr ein so großes Opfer bringt, {name}. Eure Taten hier werden niemals in Vergessenheit geraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[86359] = { id = 86359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach K'aresh", description = "Also gut, es kann losgehen. Wie kommen wir dahin?", sourceObjective = "Kehrt zur Oase von K'aresh zurück.", completion = "Ich habe mich auf diesen Moment vorbereitet, und trotzdem bin ich... nervös. Ihr könnt nun gehen, {name}. Der Autor und ich haben viel zu besprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[86360] = { id = 86360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die fabelhafte Füchsin", description = "Die Dornschweife jagen nicht, wie sie sollten?\n\nVe'nari meinte, dass Schoßkäfer nicht ihre übliche Beute seien. Wir müssen der Matriarchin selbst beibringen, wie man sie jagt!", sourceObjective = "Bringt der Dornschweifmatriarchin 10-mal bei, wie man Schoßkäferkrabbler jagt.", completion = "Hättet Ihr meinem jüngeren Ich erzählt, dass ich Tieren das Jagen beibringen würde, hätte ich Euch ausgelacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[86361] = { id = 86361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr macht mich fuchsig!", description = "Wir müssen sicherstellen, dass die Reflexe der Dornschweifjungen scharf sind, damit sie zu effektiven Jägern heranwachsen.\n\nBitte nehmt diesen Ball und lasst ein Junges ihm hinterherjagen. Alles für die Wissenschaft, versteht sich.", sourceObjective = "Fangt einen Ball 10-mal, während Ihr mit Eurem Dornschweifjungen spielt.", progress = "Wurde ein Jungtier ausreichend trainiert?", completion = "Ausgezeichnet. Spielen kann genauso nützlich sein wie Training - in manchen Fällen zumindest.", sourceObjectiveStatus = "unverified-source-field" }
quests[86362] = { id = 86362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wovon träumt der Fuchs?", description = "Ich hätte gern ein paar medizinische Daten über den Zustand der Dornschweife. Bitte besorgt für mich ein paar Blutproben.\n\nBenutzt das hier, um die Kreaturen zu betäuben. Nachdem Ihr sie entfernt, sollte auf den Pfeilen mehr als genug Blut für die Proben sein.", sourceObjective = "Sammelt 5 Blutproben.", progress = "Habt Ihr die benötigten Proben gesammelt?", completion = "Fantastisch! Genau was ich brauche. Würde Euch vielleicht eine Vollzeitstelle hier zusagen?", sourceObjectiveStatus = "unverified-source-field" }
quests[86363] = { id = 86363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der bessere Teil der Tapferkeitssteine", description = "Unsere Ankunft in Dornogal ist bereits Monate her, aber wir haben noch immer so viel über Tapferkeitssteine zu lernen. Wie sich herausgestellt hat, findet man sie auch außerhalb von Azeroth! Diese Entdeckung erschließt uns vollkommen neue Forschungsmöglichkeiten.\n\nNeue Forschung bringt Bedarf an neuen Vorräten. Bringt mir ein paar und wir werden Eure Ausrüstung auf ein völlig neues Niveau aufwerten.", sourceObjective = "Sammelt 50 Tapferkeitssteine auf Euren Reisen durch Khaz Algar, Lorenhall und K'aresh. Kehrt dann zu Cuzolth zurück und verbessert ein Stück Eurer Ausrüstung aus Saison 3.", progress = "Es hat keine Eile. Aber vielleicht beeilt Ihr Euch trotzdem ein wenig...", completion = "Ihr seid eine Wucht! Ich wusste, dass ich mich auf Euch verlassen kann. Hier habt Ihr eine Kleinigkeit für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[86364] = { id = 86364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wappen aus dem Äther", description = "Wunderbar. Tapferkeitssteine können Ausrüstungsteile niedrigerer Stufen aufwerten.\n\nDennoch ist ihre Wirkungskraft beschränkt. Für mächtigere Ausrüstung werdet Ihr auch Astralwappen benötigen, um ihr volles Potenzial auszuschöpfen. Diese Wappen werden durch viele verschiedene Aktivitäten vergeben. Für Astralwappen gibt es vier Stufen, und gefährlichere Aufgaben bringen Wappen höherer Stufen ein.\n\nBringt mir 15 verwitterte Astralwappen, dann können wir einen Teil Eurer Ausrüstung aufwerten.", sourceObjective = "Besorgt 15 verwitterte Astralwappen, indem Ihr einzigartige Kreaturen besiegt, Schlachtzüge bezwingt, Weltquests abschließt oder Schätze plündert. Kehrt dann zu Vaskarn in Dornogal zurück.", progress = "Wenn Ihr Schwierigkeiten habt, verwitterte Astralwappen zu finden, könnt Ihr in Khaz Algar, Lorenhall oder K'aresh nach versteckten Schätzen suchen. Dort gibt es jede Menge dieser Schätze!", completion = "Wunderbar. Ich freue mich schon, dass Ihr noch mächtiger werdet! Und natürlich, dass meine Forschung weiter vorangetrieben wird. Aber ja, machen wir Euch noch mächtiger!", sourceObjectiveStatus = "unverified-source-field" }
quests[86365] = { id = 86365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wappentransmutation", description = "Meine Güte, diese Wappen sind vorzüglich. Es sieht aus, als könnten sie zu verschiedenen Stufen transmutiert werden!\n\nWenn Ihr keinen Bedarf mehr an Wappen niedrigerer Stufen haben solltet, kann ich sie zu mächtigeren Wappen transmutieren. Aber ich kann auch Wappen zu einer niedrigeren Stufe transmutieren.\n\nLasst uns den Transmutationsprozess üben. Hier sind ein paar geschnitzte Astralwappen. Sprecht mit mir und ich kann sie für Euch zu verwitterten Astralwappen transmutieren.", sourceObjective = "Bringt 15 geschnitzte Astralwappen zu Vaskarn in Dornogal und tauscht sie gegen einen Beutel verwitterter Astralwappen ein.", progress = "Wenn Ihr diese geschnitzten Astralwappen verliert, findet Ihr bei mächtigen Kreaturen auf K'aresh weitere. Es soll ja die verschiedensten geben!", completion = "Bemerkenswert!\n\nBeachtet, dass ich Wappen nur zu einer höheren Stufe transmutieren kann, wenn Ihr keinen Nutzen mehr für sie habt, und dass das ein kostspieliger Prozess sein wird. Vielen Dank für all Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
